/**
 * Script para cerrar menu sidebar Mobile presionado fuera del sidebar
 */

// Evita que el evento de clic en btnLogoCabecera se propague
if (btnLogoCabecera) {
    btnLogoCabecera.addEventListener("click", function (event) {
        event.stopPropagation(); // Detiene la propagación del evento
    });
}

document.addEventListener("click", function (event) {
    // Si el sidebar no está abierto, no hacer nada
    if (sidebar && !sidebar.classList.contains("!left-[0px]")) return;

    // Si el clic es dentro del sidebar o en los botones, salir
    if (
        event.target.closest("#sidebar_desktop") ||
        event.target === btnToggleMenu
    ) {
        return;
    }

    // Evitar que el setTimeout se ejecute si el clic fue en btnLogoCabecera
    if (event.target === btnLogoCabecera) return;

    // Retraso opcional para UX
    setTimeout(() => {
        toggleMenu();
        eliminarOverlay();
    }, 100); // Reducir el tiempo de espera
});



/**
 * Funcion que inicializa ciertas variables
 */
function init(flag_protect) {
    $('body').dblclick(function (e) {
        e.preventDefault();
        e.stopImmediatePropagation();
    });

    if (informeProcess == 1) {
        setTimeout(init, 300000, false);
        return;
    }

    if (isRequestActive) {
        console.log("Petición bloqueada, Vamos a Reintentar.");
        setTimeout(init, RETRY_DELAY, flag_protect);
        return;
    }

    var url = "../common/chequea_notificaciones.php";
    var ajax = objetoAjax();

    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            isRequestActive = false;
            if (ajax.status == 200) {
                if (flag_protect) {
                    esperaRespuesta(false);
                }
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);

                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        if (jsonData.notificaciones) {
                            showNotificacionesIcon(true);
                            verNotificaciones();
                        } else if (muestra_indicadores) {
                            activaIndicadores();
                        }

                        $(function () {
                            $.datepicker.setDefaults($.datepicker.regional["es"]);
                            $("#fecha_inicio_puestos").datepicker({
                                firstDay: 1,
                                dateFormat: "dd-mm-yy"
                            });
                        });
                    }
                    setTimeout(init, 300000, false);
                }
            } else if (ajax.status == 404) {
                showDialog(error404, 1);
            } else if (ajax.status !== 0) {
                showDialog("Error:" + ajax.status, 1);
            }
        }
    };

    isRequestActive = true;
    esperaRespuesta(flag_protect);
    ajax.send(null);
}




