                                var arrSelectedEA = new Array();
                                for (var i = 0; i < selEncuestaAsignacion.options.length; i++) {
                                    if (selEncuestaAsignacion.options[i].selected) {
                                        arrSelectedEA.push(selEncuestaAsignacion.options[i].value);
                                    }
                                }
                                if (arrSelectedEA.length > 0) {
                                    idEncuestasAsignacion = arrSelectedEA.join();
                                }
