/**
 * Funcion que chequea si hay seleccionados para acciones multiples
 *
 */
function toggleAccionMultiple(elemento) {
    if (elemento != null) {
        if (elemento.checked == true) {
            idSeleccionadas.push(elemento.value);
        } else {
            var copia = idSeleccionadas;
            idSeleccionadas = new Array();
            for (var i = 0; i < copia.length; i++) {
                if (copia[i] != elemento.value) {
                    idSeleccionadas.push(copia[i]);
                }
            }
        }
    }
    var flagActivo = false;
    var arrIds = new Array();
    var arrInput = document.getElementsByTagName('input');
    for (var i = 0; i < arrInput.length; i++) {
        if (arrInput[i].type == 'checkbox' && arrInput[i].name == 'id' && arrInput[i].checked == true) {
            flagActivo = true;
            arrIds.push(arrInput[i].value);
        } else if (arrInput[i].type == 'text' && arrInput[i].name.indexOf('combinar_') >= 0 && arrInput[i].disabled == false) {
            arrInput[i].disabled = true;
            arrInput[i].style.display = "none";
        }
    }
    if (idSeleccionadas.length > 0 && flagActivo == false) {
        flagActivo = true;
    }
    var arrDiv = document.getElementsByTagName("div");
    for (var i = 0; i < arrDiv.length; i++) {
        if (arrDiv[i].classList.contains("accion_multiple")) {
            if (flagActivo == true) {
                arrDiv[i].style.display = "block";
            } else {
                arrDiv[i].style.display = "none";
            }
            redondearBordes();
        }
    }
    if (flagActivo == true) {
        for (var i = 0; i < arrIds.length; i++) {
            if (document.getElementById("combinar_inicio_" + arrIds[i]) != null) {
                var inputBox = document.getElementById("combinar_inicio_" + arrIds[i]);
                inputBox.style.display = "block";
                inputBox.disabled = false;
                $(function () {
                    $.datepicker.setDefaults($.datepicker.regional["es"]);
                    $("#combinar_inicio_" + arrIds[i]).datepicker({
                        firstDay: 1,
                        dateFormat: "dd-mm-yy"
                    });
                });
            }
            if (document.getElementById("combinar_fin_" + arrIds[i]) != null) {
                var inputBox = document.getElementById("combinar_fin_" + arrIds[i]);
                inputBox.style.display = "block";
                inputBox.disabled = false;
                $(function () {
                    $.datepicker.setDefaults($.datepicker.regional["es"]);
                    $("#combinar_fin_" + arrIds[i]).datepicker({
                        firstDay: 1,
                        dateFormat: "dd-mm-yy"
                    });
                });
            }
        }
    } else {
        for (var i = 0; i < arrIds.length; i++) {
            if (document.getElementById("combinar_inicio_" + arrIds[i]) != null) {
                var inputBox = document.getElementById("combinar_inicio_" + arrIds[i]);
                inputBox.style.display = "none";
                inputBox.disabled = true;
            }
            if (document.getElementById("combinar_fin_" + arrIds[i]) != null) {
                var inputBox = document.getElementById("combinar_fin_" + arrIds[i]);
                inputBox.style.display = "none";
                inputBox.disabled = true;
            }
        }
    }
}


/**
 * Funcion que chequea si hay seleccionados para activar tarjetas de empleados y muestra u oculta el boton de acción
 *
 */
function toggleAccionActivar(elemento) {
    if (elemento != null) {
        if (elemento.checked == true) {
            idActivar.push(elemento.value);
        } else {
            var copia = idActivar;
            idActivar = new Array();
            for (var i = 0; i < copia.length; i++) {
                if (copia[i] != elemento.value) {
                    idActivar.push(copia[i]);
                }
            }
        }
    }
    var flagActivo = false;
    var arrIds = new Array();
    var arrInput = document.getElementsByTagName('input');
    for (var i = 0; i < arrInput.length; i++) {
        if (arrInput[i].type == 'checkbox' && arrInput[i].name == 'activar' && arrInput[i].checked == true) {
            flagActivo = true;
            arrIds.push(arrInput[i].value);
        }
    }
    if (idActivar.length > 0 && flagActivo == false) {
        flagActivo = true;
    }
    var arrDiv = document.getElementsByTagName("div");
    for (var i = 0; i < arrDiv.length; i++) {
        if (arrDiv[i].classList.contains("accion_activar")) {
            if (flagActivo == true) {
                arrDiv[i].style.display = "block";
                $(".botonCheck").removeClass("rounded-full");
                $(".botonCheckGroup").removeClass("rounded-r-full");
                $(".botonCheck").addClass("rounded-l-full");
                if ($("#tarjetasDesactivadas").is(":visible")) {
                    $("#tarjetasActivadas").removeClass("rounded-r-full");
                    $("#tarjetasDesactivadas").removeClass("rounded-full");
                    $("#tarjetasDesactivadas").addClass("rounded-r-full");
                } else {
                    $("#tarjetasActivadas").addClass("rounded-r-full");
                }
            } else {
                arrDiv[i].style.display = "none";
                $(".botonCheck").removeClass("rounded-l-full");
                $(".botonCheck").addClass("rounded-full");
                $(".botonCheckGroup").addClass("rounded-r-full");
                if (!$("#tarjetasDesactivadas").is(":visible")) {
                    $("#tarjetasActivadas").addClass("rounded-l-full");
                    $("#tarjetasDesactivadas").removeClass("rounded-r-full");
                    $("#tarjetasDesactivadas").addClass("rounded-full");
                } else {
                    $(".botonCheck").removeClass("rounded-full");
                    $(".botonCheck").addClass("rounded-l-full");
                    $("#tarjetasDesactivadas").removeClass("rounded-r-full");
                    $("#tarjetasDesactivadas").addClass("rounded-full");
                }
            }
        }
    }
}

