/**
 * Funcion que recarga los calendarios de eventos de una empresa
 *
 */
function reloadCalendariosEventos(selectBox, menu_opcion, submenu_opcion) {
    if (selectBox != null) {
        var empresa_id = selectBox.options[selectBox.selectedIndex].value;
        calEventosSelect = document.getElementById("id_calendarios_eventos");
        texto = calEventosSelect.options[0].text;
        calEventosSelect.options.length = 0;
        calEventosSelect.options[0] = new Option(texto, "");

        if (empresa_id != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_calendarios_eventos.php?id=" + empresa_id + "&op=" + menu_opcion + "&sub=" + submenu_opcion;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);
                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var arr_cal_eventos = jsonData.cal_eventos;
                                var listaEmpleados = jsonData.empleados
                                if (calEventosSelect != null) {
                                    for (var key in arr_cal_eventos) {
                                        if (arr_cal_eventos.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {
                                            calEventosSelect.options[calEventosSelect.options.length] = new Option(arr_cal_eventos[key], key);
                                        }
                                    }
                                }
                                var selectEmpleados = document.getElementById('filtro_empleados_mult');
                                if (selectEmpleados != null && selectEmpleados != undefined) {
                                    var cajaEmpleados = selectEmpleados.parentNode;
                                    cajaEmpleados.innerHTML = listaEmpleados;
                                    $(function () {
                                        $("#filtro_empleados_mult").pqSelect({
                                            multiplePlaceholder: seleccionar_empleados,
                                            displayText: mensaje_filtro_seleccionados,
                                            deselect: true,
                                            selectallText: seleccionar_todos,
                                            checkbox: true,
                                            maxDisplay: 0,
                                            search: true
                                        }).on("change", function (evt) {
                                            var val = $(this).val();
                                            var idEmpleados = document.getElementById("lista_empleados");
                                            if (idEmpleados != null) {
                                                idEmpleados.value = val;
                                            }
                                        });
                                    });
                                }
                                var inputListaEmpl = document.getElementById("lista_empleados");
                                if (inputListaEmpl != null && inputListaEmpl != undefined) {
                                    inputListaEmpl.value = "";
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

