/**
 * Funcion que recarga la lista de Tipos de Incidencia
 *
 */
function reloadIncidenciasTipo(selectBox, menu_opcion, submenu_opcion, idEmpleado) {
    if (selectBox != null) {
        var texto = selectBox.options[0].text;
        selectBox.options.length = 0;
        selectBox.options[0] = new Option(texto, "");

        if (idEmpleado != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_incidenciastipo.php?id=" + idEmpleado + "&op=" + menu_opcion + "&sub=" + submenu_opcion;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);
                            if (jsonData.status == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.status == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else {
                                var arrIdIncidencias = jsonData.id_incidencias;
                                var arrIncidencias = jsonData.incidencias;
                                var arrMaxHoras = jsonData.max_horas;
                                var arrConsumido = jsonData.consumidos;
                                var arrDisponible = jsonData.disponible;
                                for (var ind = 0; ind <= (arrIdIncidencias.length - 1); ind++) {
                                    selectBox.options[selectBox.options.length] = new Option(arrIncidencias[ind], arrIdIncidencias[ind]);
                                }
                                var labelHorasExtras = document.getElementById("horas_extras_disponibles");
                                var labelJornadaIrregular = document.getElementById("jornada_irregular_disponible");
                                var labelHorasBolsaAntAsignados = document.getElementById("dias_asignados_bolsa");
                                var labelHorasBolsaAntConsumido = document.getElementById("dias_consumidos_bolsa");
                                var labelHorasBolsaAntDisponible = document.getElementById("dias_disponibles_bolsa");
                                if (labelHorasExtras != null || labelJornadaIrregular != null) {
                                    getHorasExtras(menu_opcion, submenu_opcion, idEmpleado);
                                }
                                if (labelHorasBolsaAntAsignados != null || labelHorasBolsaAntConsumido != null || labelHorasBolsaAntDisponible != null) {
                                    getHorasBolsaAnioAnt(menu_opcion, submenu_opcion, idEmpleado);
                                }
                                for (var ind = 0; ind <= (arrMaxHoras.length - 1); ind++) {
                                    if (arrMaxHoras[ind] != "" && arrMaxHoras[ind] != null) {
                                        var capsulaA = document.getElementById(arrIdIncidencias[ind] + '_a');
                                        if (capsulaA == null || capsulaA == "") {
                                            //Localizar formulario
                                            var formulario = document.getElementById("nuevo_elemento");
                                            //Salto de linea
                                            var nuevaLinea = document.createElement("div");
                                            nuevaLinea.classList.add("clear");
                                            formulario.appendChild(nuevaLinea);
                                            //Contenedor asignados
                                            var capsula = document.createElement("div");
                                            capsula.classList.add("item_elemento");
                                            var texto_asignado = document.createElement("label");
                                            texto_asignado.classList.add("force");
                                            texto_asignado.innerHTML = (textoHoras + ' ' + arrIncidencias[ind] + ':');
                                            texto_asignado.style.textTransform = "capitalize";
                                            capsula.appendChild(texto_asignado);
                                            var texto_valor = document.createElement("label");
                                            texto_valor.innerHTML = arrMaxHoras[ind];
                                            texto_valor.id = arrIdIncidencias[ind] + '_a';
                                            capsula.appendChild(texto_valor);
                                            formulario.appendChild(capsula);
                                            //Contenedor consumidos
                                            var capsula2 = document.createElement("div");
                                            capsula2.classList.add("item_elemento");
                                            var texto_consumido = document.createElement("label");
                                            texto_consumido.classList.add("force");
                                            texto_consumido.innerHTML = (textoConsumidos + ':');
                                            capsula2.appendChild(texto_consumido);
                                            var consumido_valor = document.createElement("label");
                                            consumido_valor.innerHTML = arrConsumido[ind];
                                            consumido_valor.id = arrIdIncidencias[ind] + '_c';
                                            capsula2.appendChild(consumido_valor);
                                            formulario.appendChild(capsula2);
                                            //Contenedor disponibles
                                            var capsula3 = document.createElement("div");
                                            capsula3.classList.add("item_elemento");
                                            var texto_disponibles = document.createElement("label");
                                            texto_disponibles.classList.add("force");
                                            texto_disponibles.innerHTML = (textoDisponibles + ':');
                                            capsula3.appendChild(texto_disponibles);
                                            var disponible_valor = document.createElement("label");
                                            disponible_valor.innerHTML = arrDisponible[ind];
                                            disponible_valor.id = arrIdIncidencias[ind] + '_d';
                                            capsula3.appendChild(disponible_valor);
                                            formulario.appendChild(capsula3);
                                        } else {
                                            capsulaA.innerHTML = arrMaxHoras[ind];
                                            var capsulaC = document.getElementById(arrIdIncidencias[ind] + '_c');
                                            if (capsulaC != null && capsulaC != "") {
                                                capsulaC.innerHTML = arrConsumido[ind];
                                            }
                                            var capsulaD = document.getElementById(arrIdIncidencias[ind] + '_d');
                                            if (capsulaD != null && capsulaD != "") {
                                                capsulaD.innerHTML = arrDisponible[ind];
                                            }
                                        }
                                    }
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
        document.getElementById("dias_asignados_bolsa").parentNode.classList.add('oculto');
        document.getElementById("dias_consumidos_bolsa").parentNode.classList.add('oculto');
        document.getElementById("dias_disponibles_bolsa").parentNode.classList.add('oculto');

    } else {
        showDialog(invalidOption);
    }
}

