/**
 * Funcion que recarga las familias de los tipos de equipamientos
 */
function reloadTiposEquipamientosFamilias(selectBox) {
    if (selectBox != null) {
        var tipoEquipamientoId = selectBox.options[selectBox.selectedIndex].value;
        var equipamientosFamiliasSelect = document.getElementById("id_tipos_equipamientos_familias");
        var texto = equipamientosFamiliasSelect.options[0].text;
        equipamientosFamiliasSelect.options.length = 0;
        equipamientosFamiliasSelect.options[0] = new Option(texto, "");
        if (tipoEquipamientoId != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_tipos_equipamientos_familias.php?id=" + tipoEquipamientoId;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);

                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var arr_tiposEquipamientosFamilias = jsonData.familias;
                                var flagLotes = jsonData.flag_lotes;
                                if (equipamientosFamiliasSelect != null) {
                                    for (var key in arr_tiposEquipamientosFamilias) {
                                        if (arr_tiposEquipamientosFamilias.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {
                                            equipamientosFamiliasSelect.options[equipamientosFamiliasSelect.options.length] = new Option(arr_tiposEquipamientosFamilias[key], key);
                                        }
                                    }
                                }
                                if (document.getElementById('cantidad') != null) {
                                    var inputCantidad = document.getElementById('cantidad');
                                    if (flagLotes == 1) {
                                        inputCantidad.required = true;
                                        inputCantidad.parentNode.classList.remove('oculto');
                                    } else {
                                        inputCantidad.value = "";
                                        inputCantidad.required = false;
                                        inputCantidad.parentNode.classList.add('oculto');
                                    }
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    }
                    else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);

            loadDatosEquipamientos(tipoEquipamientoId);
        }
    } else {
        showDialog(invalidOption);
    }
}

