/**
 * Funcion que va a la vista de planes comparados
 *
 */
function compararCalendarios(menu_opcion, submenu_opcion, permissions_only = 0) {
    if (idSeleccionadas.length >= 2) {
        var datos = idSeleccionadas.join();
        var url = "";
        var ajax = objetoAjax();
        url = "../common/gen_view_elem.php?op=" + menu_opcion + "&sub=" + submenu_opcion + '&id=' + datos + '&perm=' + permissions_only;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            document.getElementById("content").innerHTML = arr_aux[1];
                            $(function () {
                                $.datepicker.setDefaults($.datepicker.regional["es"]);
                                $("#fecha_inicio").datepicker({
                                    firstDay: 1,
                                    dateFormat: "dd-mm-yy",
                                    changeYear: true,
                                    yearRange: "-65:+10"
                                });
                            });
                            $(function () {
                                $.datepicker.setDefaults($.datepicker.regional["es"]);
                                $("#fecha_fin").datepicker({
                                    firstDay: 1,
                                    dateFormat: "dd-mm-yy",
                                    changeYear: true,
                                    yearRange: "-65:+10"
                                });
                            });
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    } else {
        showDialog(mensaje_error_compara_calendarios_numero);
    }

}

/**
 * Funcion que sirve para filtrar calendarios comparados y mostrar solo los que tengan permisos
 *
 */
function checkMostrarSoloPermisos(menu_opcion, submenu_opcion) {
    var checkbox = document.getElementById('permissions_only');
    if (checkbox.checked) {
        compararCalendarios(menu_opcion, submenu_opcion, 1);
    } else {
        compararCalendarios(menu_opcion, submenu_opcion, 0);
    }
}


