/**
 * Funcion que rellena los campos de experiencia laboral para editar
 *
 */
function editaTab(menu_opcion, submenu_opcion, idTab, tab) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(idTab) && !isNaN(tab)) {
        var url = "";
        var ajax = objetoAjax();
        url = "../common/get_tab.php?op=" + menu_opcion + "&sub=" + submenu_opcion + '&id=' + idTab + '&tab=' + tab;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            var arrCampos = arr_aux[1].split(";");
                            for (var i = 0; i < arrCampos.length; i++) {
                                var arrElementos = arrCampos[i].split(",");
                                var campo = document.getElementById(arrElementos[0]);
                                if (campo != null && arrElementos[1] != "") {
                                    if (campo.type != "checkbox") {
                                        campo.value = arrElementos[1];
                                    } else if (campo.type == "checkbox" && arrElementos[1] == 1) {
                                        campo.checked = true;
                                    }
                                    if (campo.type == "hidden" && campo.id == "id_documentos_certificado") {
                                        campo.value = arrElementos[1];
                                        //alert(campo.value);
                                        var ver_a = document.getElementById("ver_a");
                                        var ver_ex = document.getElementById("ver_ex");
                                        if (ver_a != null && ver_ex != null) {
                                            if (campo.value != 0) {
                                                ver_a.style.display = "block";
                                                ver_ex.style.display = "none";
                                                var data = '<label>Certificado</label><a href="../common/creaDoc.php?id=' + campo.value + '"target="_blank"><b>Archivo</b></a>';
                                                document.getElementById("ver_a").innerHTML = data;
                                            } else {
                                                ver_a.style.display = "none";
                                                ver_ex.style.display = "block";
                                            }
                                        }
                                    }
                                    if (campo.type == "hidden" && campo.id == "id_archivo_titulo") {
                                        var ver_archivotitulo2 = document.getElementById("ver_archivotitulo2");
                                        var ver_archivotitulo = document.getElementById("ver_archivotitulo");
                                        if (ver_archivotitulo2 != null && ver_archivotitulo != null) {
                                            if (campo.value != 0) {
                                                ver_archivotitulo2.style.display = "block";
                                                ver_archivotitulo.style.display = "none";
                                                var data = '<label>Archivo Del Título</label><a href="../common/creaDoc.php?id=' + campo.value + '"target="_blank"><b>Archivo</b></a>';
                                                document.getElementById("ver_archivotitulo2").innerHTML = data;
                                            } else {
                                                ver_archivotitulo2.style.display = "none";
                                                ver_archivotitulo.style.display = "block";
                                            }
                                        }
                                    }

                                    /* if(campo.id == "id_archivo_titulo"){
                                        var cambiar_archivo_formacion = document.getElementById("cambiar_archivo_formacion");
                                        if(campo.value != 0){
                                            console.log("entro");
                                            cambiar_archivo_formacion.style.display= "block";
                                            var dataCambiarArchivoFormacion= '<div class="boton" onclick="cambiarArchivoFormacion(false);">Cambiar Archivo</div>';
                                            document.getElementById("cambiar_archivo_formacion").innerHTML=dataCambiarArchivoFormacion;
                                        } 
                                    } */
                                }
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    } else {
        showDialog(invalidOption);
    }
}

