/**
 * Funcion que configura el conocimiento que se va a validar
 *
 */
function puntuarConocimiento(idConocimiento) {
    if (!isNaN(idConocimiento)) {
        var url = "";
        var ajax = objetoAjax();
        url = "../common/set_conocimiento.php?id=" + idConocimiento;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            //Do nothing
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            var elements = document.getElementsByTagName('div');
                            for (var i = 0; i < elements.length; i++) {
                                if (elements[i].className.indexOf('validar') >= 0 && tab_activo != elements[i]) {
                                    tab_activo.style.display = "none";
                                    elements[i].style.display = "block";
                                    tab_activo = elements[i];
                                }
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(null);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que da o quita monedas a un empleado en un conocimiento
 *
 */
function accionMoneda(menu_opcion, submenu_opcion, accion) {
    if (idEmpleadosJuego > 0 && idEmpleadosJuego != "") {
        if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(accion)) {
            var formulario = document.getElementById("nuevo_elemento");
            var longitudFormulario = formulario.elements.length;
            var formData = new FormData();
            formData.append('op', menu_opcion);
            formData.append('sub', submenu_opcion);
            formData.append('accion', accion);
            formData.append('id_empleados_destino', idEmpleadosJuego);
            var re = /^\w+$/;
            //var re2 = /(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).{6,}/;
            for (var i = 0; i <= (longitudFormulario - 1); i++) {
                if (formulario.elements[i].required == true && formulario.elements[i].value == "") {
                    showDialog(mensaje_faltan_campos, 1);
                    formulario.elements[i].classList.add("requerido");
                    return false;
                } else if (formulario.elements[i].name == "name" && !re.test(formulario.elements[i].value)) {
                    showDialog(formulario.elements[i].name + mensaje_error_caracteres);
                    return false;
                }
                formData.append(formulario.elements[i].name, formulario.elements[i].value);
            }
            var url = "";
            var ajax = objetoAjax();
            url = "../common/accion_moneda.php";
            ajax.open("POST", url, true);
            //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                showDialog(arr_aux[1]);
                                irAContenido(menu_activo, menu_opcion, submenu_opcion);
                                idEmpleadosJuego = 0;
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                }
            };
            ajax.send(formData);
            esperaRespuesta(true);
        } else {
            showDialog(invalidOption);
        }
    } else {
        showDialog(mensaje_error_empleado_juego);
    }
}

