/**
 * Funcion que chequea funcionamiento de AJAX POST
 *
 */
function checkNavegador(flag_movil) {
    var json = { 'test': '1' };
    var formData = new FormData();
    formData.append('test', 1);
    var url = "";
    var ajax = objetoAjax();;
    url = "./common/check_navegador.php";
    ajax.open("POST", url, true);
    if (flag_movil == 1) {
        ajax.setRequestHeader('Content-Type', 'application/json; charset=UTF-8');
    }
    //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                var html_txt = ajax.responseText;
                if (html_txt != 1) {
                    window.location = "navegadores.php";
                }
            } else if (ajax.status == 404) {
                showDialog(error404, 1);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status, 1);
            }
        }
    };
    if (flag_movil == 1) {
        ajax.send(JSON.stringify(json));
    } else {
        ajax.send(formData);
    }

}

