/**
 * Funcion que fuerza el reenvio de mail de aceptacion de recurso
 *
**/
function reenvioRecurso(idRecurso, operacion) {
    if (!isNaN(idRecurso) && operacion != "") {
        var jsonObj = {};
        jsonObj.id = idRecurso;
        jsonObj.operacion = operacion;

        var url = "";
        var ajax = objetoAjax();;
        url = "../common/reenvia_mail_recurso.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        showDialog(jsonData.mensaje);
                        if (jsonData.estado == 1) {
                            return;
                        } else if (jsonData.estado == 2) {
                            window.location = "../inc/salir.php";
                        } else {
                            return;
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    esperaRespuesta(false);
                    showDialog(error404, 1);
                }
                else if (ajax.status != 0) {
                    esperaRespuesta(false);
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(JSON.stringify(jsonObj));
        esperaRespuesta(true);
    }
}


