/**
 * Funcion que para asignar día fectivo a un plan determinado
 *
 */

function modalDiferenciaFestivos(menu_opcion, submenu_opcion, plan_id, centro_id, botones = 0) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && plan_id != "") {
        var url = "";
        var ajax = objetoAjax();
        url = "../common/gen_diferencia_festivo.php?op=" + menu_opcion + "&sub=" + submenu_opcion + '&id_plan=' + plan_id + '&id_centro=' + centro_id;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            showDialog(arr_aux[1], 'Diferencia de Días Festivos');
                            // document.getElementById("content").innerHTML = arr_aux[1];
                            // toggleAccionActivar(null);
                            // toggleAccionDesactivar(null);
                        }
                    } else {
                        showDialog(noResults);
                    }
                    if (botones == 1) {
                        $("#botonPrincipal").addClass("!hidden");
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion para actualizar festivos
 *  
 */

function actualizarFestivos(menu_opcion, submenu_opcion, tipo_operacion, flag_mobil = 0) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && tipo_operacion != "") {
        let formData = new FormData();
        let tipo_formulario;
        if (tipo_operacion == 1) {
            tipo_formulario = "fechaplan";
        } else {
            tipo_formulario = "fechacale";
        }
        let procesados = 0;
        let formulario = document.getElementById('form_festivo');
        let longitudFormulario = formulario.elements.length;
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        formData.append('tip_oper', tipo_operacion);

        for (var i = 0; i <= (longitudFormulario - 1); i++) {
            if (formulario.elements[i].checked == true) {
                procesados++;
                nombre = formulario.elements[i].name;
                prueba = nombre.substr(0, 9);
                if (nombre.substr(0, 9) == tipo_formulario) {
                    if (tipo_operacion == 1) {
                        id_plan = formulario.elements[i].getAttribute("id_plan");
                        formData.append('id_plan[]', id_plan);
                        fecha = formulario.elements[i].getAttribute("fecha");
                        formData.append('fecha[]', fecha);
                        tipo = formulario.elements[i].getAttribute("tipo");
                        formData.append('tipo[]', tipo);
                        id_calendario = formulario.elements[i].getAttribute("id_calendario");
                        formData.append('id_calendario[]', id_calendario);
                    } else {
                        id_plan = formulario.elements[i].getAttribute("id_plan");
                        formData.append('id_plan[]', id_plan);
                        id_centro = formulario.elements[i].getAttribute("id_centro");
                        formData.append('id_centro[]', id_centro);
                        fecha = formulario.elements[i].getAttribute("fecha");
                        formData.append('fecha[]', fecha);
                        tipo = formulario.elements[i].getAttribute("tipo");
                        formData.append('tipo[]', tipo);
                    }
                }
            }
        }
        if (procesados > 0) {
            var url = "";
            var ajax = objetoAjax();
            url = "../common/save_festivos.php";
            ajax.open("POST", url, true);
            //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        informeProcess = 0;
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                hideDialog();
                                showDialog(arr_aux[1]);
                            }
                        } else {
                            showDialog(noResults);
                        }

                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                    irAContenido(menu_activo, menu_opcion, submenu_opcion);
                }
            };
            informeProcess = 1;
            if (flag_mobil == undefined || flag_mobil == 0) {
                ajax.send(formData);
            } else {
                ajax.send(JSON.stringify(jsonObj));
            }
            esperaRespuesta(true);
        } else {
            showDialog(no_festivos);
        }

    } else {
        showDialog(invalidOption);
    }
}


