/**
 * Funcion que va al modulo que genero la notificacion
 *
 */
function irANotificacion(id) {
    var url = "";
    var ajax = objetoAjax();
    url = "../common/go_notificaciones.php?id=" + id;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] == 1) {
                        showDialog(arr_aux[1]);
                    } else if (arr_aux[0] == 2) {
                        showDialog(arr_aux[1]);
                        flag_echar = true;
                    } else {
                        var notificacion = JSON.parse(arr_aux[1]);
                        var seccion_id = 0;
                        var elemento_id = 0;
                        if (notificacion.seccion_id != null && notificacion.elemento_id != null) {
                            seccion_id = notificacion.seccion_id;
                            elemento_id = notificacion.elemento_id;
                        } else if (notificacion.seccion_emp_id != null && notificacion.elemento_emp_id != null) {
                            seccion_id = notificacion.seccion_emp_id;
                            elemento_id = notificacion.elemento_emp_id;
                        }
                        if (notificacion.operacion == "INFORMDOWN") {
                            window.open(notificacion.mensaje);
                        } else if (seccion_id != 0 && elemento_id != 0) {
                            irAContenido(menu_activo, seccion_id, elemento_id);
                        }

                        showNotificacionesIcon(notificacion.icono);
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404, 1);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status, 1);
            }
        }
    };
    esperaRespuesta(true);
    ajax.send(null);
}


/**
 * Funcion que pasa equipamientos a la lista de asignados para que sean despues guardados
 *
 */
function addEquipoToEntrega(menu_opcion, submenu_opcion, accion) {
    var arrInput = document.getElementsByTagName('input');
    var arrIdStock = new Array();
    if (arrInput != null) {
        for (var i = 0; i < arrInput.length; i++) {
            if (arrInput[i].type == "checkbox" && arrInput[i].id == "id_equipamientos_stock" && arrInput[i].checked == true) {
                //Es un equipamiento seleccionado
                arrIdStock.push(arrInput[i].value);
            }
        }
        if (arrIdStock.length > 0) {
            //Equipamientos almacenados enviamos a background para tenerlos disponibles en sesion
            var jsonIdStock = JSON.stringify(arrIdStock);

            var url = "";
            var ajax = objetoAjax();
            url = "../common/asignacion_equipamientos.php?op=add&eq=" + jsonIdStock;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);
                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                                return;
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else {
                                if (accion == accionLista) {
                                    irAContenido(menu_activo, menu_opcion, submenu_opcion);
                                } else if (accion == accionFormulario) {
                                    nuevoElemento(menu_opcion, submenu_opcion, null);
                                } else if (accion == accionEdicion) {
                                    editaElemento(menu_opcion, submenu_opcion, idEmpleados);
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    }
}

