/**
 * Funcion comprueba los dias consumidos y disponibles de un empleado para un horario
 *
 */
function checkVacations(menu_opcion, submenu_opcion, idEmpleados) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(idEmpleados)) {
        var selectHorarios = document.getElementById("id_horarios");
        var idHorarios = 0;
        if (selectHorarios == null || selectHorarios.selectedIndex == 0) {
            //No hay horario seleccionado no hay accion
            return;
        } else if (selectHorarios.options == null && selectHorarios.type == "hidden") {
            //No hay select campo fijo
            idHorarios = selectHorarios.value;
        } else {
            idHorarios = selectHorarios.options[selectHorarios.selectedIndex].value;
        }
        var selectImputacion = document.getElementById("imputacion");
        var imputacion = 0;
        if (selectImputacion == null || selectImputacion.selectedIndex == 0) {
            //No hay imputacion seleccionado no hay accion
            return;
        } else {
            imputacion = selectImputacion.options[selectImputacion.selectedIndex].value;
        }
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/check_vacaciones.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&id=" + idEmpleados + "&hor=" + idHorarios + "&yr=" + imputacion;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        if (jsonData.estado == 1) {
                            showDialog(jsonData.mensaje);
                            return;
                        } else if (jsonData.estado == 2) {
                            showDialog(jsonData.mensaje);
                            flag_echar = true;
                        } else {
                            var diasAsignados = jsonData.asignados;
                            var diasConsumidos = jsonData.consumidos;
                            var diasDisponibles = jsonData.disponibles;
                            var flagVacacionesHoras = jsonData.vacaciones_horas;
                            if (document.getElementById("dias_asignados") != null) {
                                //document.getElementById("dias_asignados").innerHTML = diasAsignados;
                                document.getElementById("dias_asignados").value = diasAsignados;
                            }
                            if (document.getElementById("dias_consumidos") != null) {
                                //document.getElementById("dias_consumidos").innerHTML = diasConsumidos;
                                document.getElementById("dias_consumidos").value = diasConsumidos;
                            }
                            if (document.getElementById("dias_disponibles") != null) {
                                //document.getElementById("dias_disponibles").innerHTML = diasDisponibles;
                                document.getElementById("dias_disponibles").value = diasDisponibles;
                            }
                            if (flagVacacionesHoras == true) {
                                if (document.getElementById("hora_inicio") != null) {
                                    document.getElementById("hora_inicio").parentNode.classList.remove('oculto');
                                }
                                if (document.getElementById("hora_fin") != null) {
                                    document.getElementById("hora_fin").parentNode.classList.remove('oculto');
                                }
                            } else {
                                if (document.getElementById("hora_inicio") != null) {
                                    document.getElementById("hora_inicio").parentNode.classList.add('oculto');
                                }
                                if (document.getElementById("hora_fin") != null) {
                                    document.getElementById("hora_fin").parentNode.classList.add('oculto');
                                }
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                    esperaRespuesta(false);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                    esperaRespuesta(false);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    }
}

