/**
 * Funcion que revisa si existe ya un DNI para no volver a recoger usuario y password para ese empleado
 *
 */
function checkUser(menu_opcion, submenu_opcion, campoDNI) {
    if (campoDNI != null && campoDNI != undefined && campoDNI.value != "") {
        var dni = campoDNI.value;
        var idEmpleados = document.getElementById("id");
        var id = null;
        if (idEmpleados != null) {
            id = idEmpleados.value;
        }
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        formData.append('id', id);
        formData.append('dni', dni);

        var url = "";
        var ajax = objetoAjax();
        url = "../common/chequea_dni.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        if (jsonData.estado == 1) {
                            showDialog(jsonData.mensaje);
                            return;
                        } else if (jsonData.estado == 2) {
                            showDialog(jsonData.mensaje);
                            flag_echar = true;
                        } else {
                            if (jsonData.empleados != 0) {
                                //Ya existe ese DNI por lo que se utilizará su usuario,contraseña y roles
                                showDialog(mensaje_error_existe_empleado_nuevo);
                                var campoNick = document.getElementById('nick');
                                if (campoNick != null) {
                                    campoNick.disabled = true;
                                    campoNick.required = false;
                                    campoNick.style.display = "none";
                                    campoNick.value = "";
                                }
                                var campoPass = document.getElementById('password');
                                if (campoPass != null) {
                                    campoPass.disabled = true;
                                    campoPass.required = false;
                                    campoPass.style.display = "none";
                                    campoPass.value = "";
                                }
                                var campoRePass = document.getElementById('repassword');
                                if (campoRePass != null) {
                                    campoRePass.disabled = true;
                                    campoRePass.required = false;
                                    campoRePass.style.display = "none";
                                    campoRePass.value = "";
                                }
                                var formulario = document.getElementById("nuevo_elemento");
                                if (formulario != null) {
                                    var idUsuarios = document.createElement("input");
                                    idUsuarios.name = "id_usuarios";
                                    idUsuarios.id = "id_usuarios";
                                    idUsuarios.type = "hidden";
                                    idUsuarios.value = jsonData.empleados;
                                    formulario.appendChild(idUsuarios);
                                }
                            } else if (id != null) {
                                //No existe ese DNI por lo que se habilitan usuario,contraseña y roles
                                var campoNick = document.getElementById('nick');
                                if (campoNick != null) {
                                    campoNick.disabled = false;
                                    campoNick.required = true;
                                    campoNick.style.display = "block";
                                }
                                var campoPass = document.getElementById('password');
                                if (campoPass != null) {
                                    campoPass.disabled = false;
                                    campoPass.required = false;
                                    campoPass.style.display = "block";
                                }
                                var campoRePass = document.getElementById('repassword');
                                if (campoRePass != null) {
                                    campoRePass.disabled = false;
                                    campoRePass.required = false;
                                    campoRePass.style.display = "block";
                                }
                                var idUsuarios = document.getElementById("id_usuarios");
                                if (idUsuarios != null) {
                                    idUsuarios.parentNode.removeChild(idUsuarios);
                                }
                            } else {
                                //No existe ese DNI por lo que se habilitan usuario,contraseña y roles
                                var campoNick = document.getElementById('nick');
                                if (campoNick != null) {
                                    campoNick.disabled = false;
                                    campoNick.required = true;
                                    campoNick.style.display = "block";
                                }
                                var campoPass = document.getElementById('password');
                                if (campoPass != null) {
                                    campoPass.disabled = false;
                                    campoPass.required = true;
                                    campoPass.style.display = "block";
                                }
                                var campoRePass = document.getElementById('repassword');
                                if (campoRePass != null) {
                                    campoRePass.disabled = false;
                                    campoRePass.required = true;
                                    campoRePass.style.display = "block";
                                }
                                var idUsuarios = document.getElementById("id_usuarios");
                                if (idUsuarios != null) {
                                    idUsuarios.parentNode.removeChild(idUsuarios);
                                }
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    }
}

