/**
 * Funcion que crea un plan de trabajo combinando varios
 *
 */
function combinarPlanes(menu_opcion, submenu_opcion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var arrInput = document.getElementsByTagName("input");
        var arrIdPlanes = new Array();
        var arrFechasInicio = new Array();
        var arrFechasFin = new Array();
        for (var i = 0; i < arrInput.length; i++) {
            if (arrInput[i].name == "id" && arrInput[i].checked == true) {
                //Input de plan
                arrIdPlanes.push(arrInput[i].value);
                var InputFechaInicio = document.getElementById("combinar_inicio_" + arrInput[i].value);
                arrFechasInicio.push(InputFechaInicio.value);
                var InputFechaFin = document.getElementById("combinar_fin_" + arrInput[i].value);
                arrFechasFin.push(InputFechaFin.value);
            }
        }

        var jsonDatos = {};
        jsonDatos.id = arrIdPlanes;
        jsonDatos.fechaInicio = arrFechasInicio;
        jsonDatos.fechaFin = arrFechasFin;

        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        formData.append('datos', JSON.stringify(jsonDatos));

        var url = "";
        var ajax = objetoAjax();;
        url = "../common/combina_elem.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            showDialog(arr_aux[1]);
                            limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que purga elementos borrados previamente
 *
 */
function purgarElementos(menu_opcion, submenu_opcion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var informesForm = document.getElementById("nuevo_elemento");
        var formData = new FormData();
        var id = 0;
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);

        if (informesForm != null) {
            var longitudFormulario = informesForm.elements.length;
            var arrElementos = new Array();
            for (var i = 0; i <= (longitudFormulario - 1); i++) {
                if (informesForm.elements[i].required == true && informesForm.elements[i].value == "") {
                    showDialog(mensaje_faltan_campos, 1);
                    informesForm.elements[i].classList.add("requerido");
                    return false;
                }
                if (informesForm.elements[i].name == "empleado_id") {
                    if (informesForm.elements[i].checked == true) {
                        arrElementos.push(informesForm[i].value);
                    }
                }
            }
            if (arrElementos.length > 0) {
                formData.append('empleados', arrElementos.join());
            }
        }
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/purge_elements.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    informeProcess = 0;
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            var jsonData = JSON.parse(arr_aux[1]);
                            showDialog(jsonData.mensaje);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            showDialog(arr_aux[1]);
                            verBorrados(menu_opcion, submenu_opcion);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status == 500) {
                    showDialog("El tamaño de los datos manejados es muy grande,\nreduciendo busqueda a la última semana");
                    setLastWeek(menu_opcion, submenu_opcion);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                    esperaRespuesta(false);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
        informeProcess = 1;
    } else {
        showDialog(invalidOption);
    }
}

