/**
 * Funcion que recarga la lista de Centros despues de seleccionar Empresa
 *
 */
function getDefectoFacturacion(selectBox) {
    if (selectBox != null) {
        var idProducto = selectBox.options[selectBox.selectedIndex].value;

        if (idProducto != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/get_defecto_facturacion.php?id=" + idProducto;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);

                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var defecto = jsonData.defecto;
                                if (defecto.pvp_centro != null && document.getElementById("pvp_centro") != null) {
                                    document.getElementById("pvp_centro").value = defecto.pvp_centro;
                                } else {
                                    document.getElementById("pvp_centro").value = "";
                                }
                                if (defecto.pvp_empleado != null && document.getElementById("pvp_empleado") != null) {
                                    document.getElementById("pvp_empleado").value = defecto.pvp_empleado;
                                } else {
                                    document.getElementById("pvp_empleado").value = "";
                                }
                                if (defecto.empleado_franquicia != null && document.getElementById("empleado_franquicia") != null) {
                                    document.getElementById("empleado_franquicia").value = defecto.empleado_franquicia;
                                } else {
                                    document.getElementById("empleado_franquicia").value = "";
                                }
                                if (defecto.coste_minimo_facturable != null && document.getElementById("coste_minimo_facturable") != null) {
                                    document.getElementById("coste_minimo_facturable").value = defecto.coste_minimo_facturable;
                                } else {
                                    document.getElementById("coste_minimo_facturable").value = ""
                                }
                                if (defecto.centros_maximos_facturable != null && document.getElementById("centros_maximos_facturable") != null) {
                                    document.getElementById("centros_maximos_facturable").value = defecto.centros_maximos_facturable;
                                } else {
                                    document.getElementById("centros_maximos_facturable").value = "";
                                }
                                if (defecto.numero_centros != null && document.getElementById("numero_centros") != null) {
                                    document.getElementById("numero_centros").value = defecto.numero_centros;
                                } else {
                                    document.getElementById("numero_centros").value = "";
                                }
                                if (defecto.numero_empleados != null && document.getElementById("numero_empleados") != null) {
                                    document.getElementById("numero_empleados").value = defecto.numero_empleados;
                                } else {
                                    document.getElementById("numero_empleados").value = "";
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

