function chequeaLimitesElemento(menu_opcion, submenu_opcion, filtroElemento) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(filtroElemento)) {

        var selectEmpresas = document.getElementById("id_empresas");
        if (selectEmpresas != null && selectEmpresas.options[selectEmpresas.selectedIndex].value != "") {
            var idEmpresas = selectEmpresas.options[selectEmpresas.selectedIndex].value;
        } else {
            showDialog(mensaje_falta_empresa, 1);
            return;
        }

        var url = "";
        var ajax = objetoAjax();
        url = "../common/chequea_limites.php?filtro=" + filtroElemento + "&id=" + idEmpresas;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0 && jsonData.chequeo != null) {
                                if (jsonData.chequeo == true) {
                                    showConfirm(jsonData.mensaje, guardaElemento, menu_opcion, submenu_opcion);
                                } else {
                                    guardaElemento(menu_opcion, submenu_opcion);
                                }
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

