function checkMaxCentros(selectBox, menu_opcion, submenu_opcion) {
    if (selectBox != null) {
        var empresa_id = selectBox.options[selectBox.selectedIndex].value;

        if (empresa_id != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_centros.php?id=" + empresa_id + "&op=" + menu_opcion + "&sub=" + submenu_opcion + "&lim=1";
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);
                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                                selectBox.selectedIndex = 0;
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else {
                                if (jsonData.mensaje != null) {
                                    showDialog(jsonData.mensaje);
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que recarga la lista de modelos de vehiculos
 *
 */
function reloadModelosVehiculos(selectBox) {
    if (selectBox != null) {
        var marcas_id = selectBox.options[selectBox.selectedIndex].value;
        var marcaSelect = document.getElementById("marca");
        var codigoModelosSelect = document.getElementById("id_modelos");
        var texto = codigoModelosSelect.options[0].text;
        codigoModelosSelect.options.length = 0;
        codigoModelosSelect.options[0] = new Option(texto, "");

        if (marcas_id != "") {
            var url = "";
            var ajax = objetoAjax();
            url = "../common/recarga_modelos_vehiculos.php?id=" + marcas_id;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            var arrModelosJSON = JSON.parse(arr_aux[1]);
                            for (var ind = 0; ind <= (arrModelosJSON[0].length - 1); ind++) {
                                codigoModelosSelect.options[codigoModelosSelect.options.length] = new Option(arrModelosJSON[0][ind]['nombre'], arrModelosJSON[0][ind]['id']);
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion visualizar Elementos Puesto
 *
 */
function visualizarElementosPuesto(checkbox, id = 0) {
    if (checkbox.checked == true) {
        var hora_inicio = "";
        var hora_fin = "";
        var url = "";
        var ajax = objetoAjax();
        url = "../common/obtener_fullday.php?id=" + id;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        if (jsonData.estado == 1) {
                            showDialog(jsonData.mensaje);
                            return;
                        } else if (jsonData.estado == 2) {
                            showDialog(jsonData.mensaje);
                            flag_echar = true;
                        } else {
                            if (jsonData.id != 0) {
                                document.getElementById("hora_inicio").value = jsonData.hora_inicio;
                                document.getElementById("hora_fin").value = jsonData.hora_fin;
                                document.getElementById("hora_inicio").setAttribute("disabled", true);
                                document.getElementById("hora_fin").setAttribute("disabled", true);
                                seleccionFecha(document.getElementById('hora_fin'));

                                var id_centro = document.getElementById('id_centro_puestos');
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(null);
    } else {
        document.getElementById("hora_inicio").value = "";
        document.getElementById("hora_fin").value = "";
        document.getElementById("hora_inicio").removeAttribute("disabled");
        document.getElementById("hora_fin").removeAttribute("disabled");
    }
}

/**
 * Funcion Seleccion fecha de invitados
 *
 */
function seleccionFecha(element, id = 0) {
    var flag_fechas_incongruentes = 0

    //comporbamos si existe el elemento
    if (document.getElementById('fecha_inicio').value != undefined && document.getElementById('fecha_fin').value != undefined) {
        var fecha_inicio = document.getElementById('fecha_inicio').value;
        var fecha_fin = document.getElementById('fecha_fin').value;
    } else {
        flag_fechas_incongruentes = 1;
    }
    if (flag_fechas_incongruentes == 0) {
        var hora_inicio = document.getElementById('hora_inicio').value;
        var hora_fin = document.getElementById('hora_fin').value;

        var id_2 = element.id;
        var url = "";
        var ajax = objetoAjax();
        url = "../common/obtener_cantidad_puestos.php?fecha_inicio=" + fecha_inicio + "&fecha_fin=" + fecha_fin + "&hora_inicio=" + hora_inicio + "&hora_fin=" + hora_fin + "&id=" + id;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        if (jsonData.estado == 1) {
                            showDialog(jsonData.mensaje);
                            return;
                        } else if (jsonData.estado == 2) {
                            showDialog(jsonData.mensaje);
                            flag_echar = true;
                        } else {
                            if (jsonData.id != 0) {
                                var id_centro = document.getElementById('id_centro_puestos');
                                id_centro.value = jsonData.id;
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(null);
    }
}

