function listarSinDocumento(elem) {

    $.ajax({
        url: '../common/listasindocumento.php',
        type: 'POST',
        dataType: 'html',
        data: { dato: elem },
        beforeSend: function () {
            esperaRespuesta(true);
        },
        success: function (hte) {
            //console.log(hte);
            esperaRespuesta(false);
            $("#cargaexterna").html(hte);
            $('#principal').hide();
            $('.botonera').hide();
            $('#filtrosDocumentos').hide();
            $('#filtrosDocumentos_listasindocumento').hide();
            $('#ExportReporttoPDF').hide();
            $('#ExportReporttoExcel').hide();
            $('.BotonesDocumentos').hide();
            $('.BotonesDocumentosVolver').show();
            $('#listado').show();
        }
    });

}

