/**
 * Funcion que detecta la seleccion
 *
 */
function detectCalendarSelection(fecha = null, flag_eliminar = 0) {

    /** #CASO -seleccion por rango*/
    if (document.getElementById("calendar-wrap").dataset.selection_type == 0) {
        var initial_day = document.getElementById("calendar-wrap").dataset.initial_day;
        var final_day = document.getElementById("calendar-wrap").dataset.final_day;
        var initial_month = document.getElementById("calendar-wrap").dataset.initial_month;
        var final_month = document.getElementById("calendar-wrap").dataset.final_month;
        var initial_year = document.getElementById("calendar-wrap").dataset.initial_year;
        var final_year = document.getElementById("calendar-wrap").dataset.final_year;

        var url = "";
        var ajax = objetoAjax();
        url = "../common/detectar_seleccion_mes_calendario.php?initial_day=" + initial_day + "&final_day=" + final_day + "&initial_month=" + initial_month + "&final_month=" + final_month + "&initial_year=" + initial_year + "&final_year=" + final_year;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            var jsonData = JSON.parse(html_txt);
                        }

                    } else {
                        alert("Error al llamar a la funcion que detecta la seleccion del calendario mensual");
                    }
                } else if (ajax.status == 404) {
                    alert(error404);
                } else if (ajax.status != 0) {
                    alert("Error:" + ajax.status);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);

        /** #CASO -seleccion simple*/
    } else {
        var url = "";
        var ajax = objetoAjax();
        url = "../common/detectar_seleccion_mes_calendario.php?selected_date=" + fecha + "&flag_eliminar=" + flag_eliminar;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    //console.log(html_txt);
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            var jsonData = JSON.parse(html_txt);
                        }
                    } else {
                        alert("Error al llamar a la funcion que detecta la seleccion del calendario mensual");
                    }
                } else if (ajax.status == 404) {
                    alert(error404);
                } else if (ajax.status != 0) {
                    alert("Error:" + ajax.status);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    }
}
/**
 * Funcion que pinta seleccion de los meses
 *
 */
function changeViewCalendar(menu_opcion, submenu_opcion, flag_today = 0, date = null) {

    var url = "";
    var ajax = objetoAjax();
    if (date == null) {
        url = "../common/set_change_view_calendar.php?flag_today=" + flag_today;
    } else {
        url = "../common/set_change_view_calendar.php?flag_today=" + flag_today + "&date=" + date;
    }

    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] == 1) {
                    } else if (arr_aux[0] == 2) {
                        showDialog(arr_aux[1]);
                        flag_echar = true;
                    } else {
                        irAContenido(menu_activo, menu_opcion, submenu_opcion);
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404, 1);
            }
            else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status, 1);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}

/**
 * Funcion que chequea la eliminacion de las reservas
 *
 */
function chequeaEliminacionReserva(menu_opcion, submenu_opcion, nro_puestos, centro_id) {

    //validamos que existan los datos necesarios
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= 14 && !isNaN(submenu_opcion)
        && !isNaN(nro_puestos) && nro_puestos > 0 && !isNaN(centro_id)) {

        //tomamos la cantidad de puestos que se estan solicitando
        var nuevaCantidadPuestos = document.getElementById("nro_puestos").value;

        var url = "";
        var ajax = objetoAjax();
        url = "../common/chequeaEliminacionReserva.php?nro_puestos=" + nro_puestos + "&new_nro_puestos=" + nuevaCantidadPuestos + "&id_centros=" + centro_id;

        ajax.open("GET", url, true);

        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                if (jsonData.chequeo == 1) {
                                    showConfirm(jsonData.mensaje, guardaElemento, menu_opcion, submenu_opcion);
                                } else {
                                    guardaElemento(menu_opcion, submenu_opcion);
                                }
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(null);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que recarga las rutas al cambiar de empresa en generacion de perfiles (Perfiles HARDWARE)
 *
 */
function reloadRutasPlanesAcceso(selectBox, menu_opcion, submenu_opcion) {
    if (selectBox != null) {
        var empresa_id = selectBox.options[selectBox.selectedIndex].value;


        if (empresa_id != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_lista_rutas.php?id=" + empresa_id + "&op=" + menu_opcion + "&sub=" + submenu_opcion;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);

                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var arr_rutas = jsonData.lista_rutas;
                                var tableBodyRutas = document.getElementById("listado");
                                var tableBodyRutasSel = document.getElementById("listadoseltd");

                                if (tableBodyRutas != null) {
                                    tableBodyRutas.innerHTML = "";
                                    for (var key in arr_rutas) {

                                        if (arr_rutas.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {

                                            var fila = document.createElement("tr");
                                            var celdaInput = document.createElement("td");
                                            var inputCheck = document.createElement("input");
                                            inputCheck.type = "checkbox";
                                            inputCheck.name = "ruta_id[]";
                                            inputCheck.value = arr_rutas[key]['id'];
                                            inputCheck.dataset.ruta = arr_rutas[key]['nombre'];
                                            inputCheck.onclick = function () {
                                                if (this.checked) {
                                                    //alert(this.value);
                                                    var spanRuta = document.createElement("p");
                                                    spanRuta.setAttribute("id", this.value + "span");
                                                    spanRuta.textContent = this.dataset.ruta;
                                                    tableBodyRutasSel.appendChild(spanRuta);
                                                } else {
                                                    var spanRuta = document.getElementById(this.value + "span");
                                                    spanRuta.parentNode.removeChild(spanRuta);
                                                }
                                            };
                                            celdaInput.appendChild(inputCheck);
                                            fila.appendChild(celdaInput);
                                            var celdaNombre = document.createElement("td");
                                            celdaNombre.innerHTML = arr_rutas[key]['nombre'];
                                            fila.appendChild(celdaNombre);
                                            tableBodyRutas.appendChild(fila);


                                        }
                                    }
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404, 1);
                    }
                    else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status, 1);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Divide el valor de horas semanales a diferentes imputs L-D para contratos.
 *
 */
function dividirDiarioContrato() {
    var horas = parseInt(document.getElementById('horas_semanales').value);
    var c1 = document.getElementById("flag_diarias_lunes").checked;
    var c1Value = document.getElementById("diarias_lunes");
    var c2 = document.getElementById("flag_diarias_martes").checked;
    var c2Value = document.getElementById("diarias_martes");
    var c3 = document.getElementById("flag_diarias_miercoles").checked;
    var c3Value = document.getElementById("diarias_miercoles");
    var c4 = document.getElementById("flag_diarias_jueves").checked;
    var c4Value = document.getElementById("diarias_jueves");
    var c5 = document.getElementById("flag_diarias_viernes").checked;
    var c5Value = document.getElementById("diarias_viernes");
    var c6 = document.getElementById("flag_diarias_sabado").checked;
    var c6Value = document.getElementById("diarias_sabado");
    var c7 = document.getElementById("flag_diarias_domingo").checked;
    var c7Value = document.getElementById("diarias_domingo");



    let checkboxes = [c1, c2, c3, c4, c5, c6, c7];
    var cont = 0;

    checkboxes.forEach(function (chec, index) {
        if (chec == true) {
            cont = cont + 1;
        }
    });

    var valorhoras = Math.round(horas / cont);
    var horas_checked = 0;
    if (c1 == true) {
        document.getElementById("diarias_lunes").value = valorhoras
        horas_checked = horas_checked + valorhoras;
        console.log("horas checked 1:", valorhoras);  // Add this line to check the value
    } else {
        document.getElementById("diarias_lunes").value = "";
        horas_checked = horas_checked + valorhoras;
        console.log("horas checked 1:", valorhoras);  // Add this line to check the value
    }
    if (c2 == true) {
        document.getElementById("diarias_martes").value = valorhoras
        horas_checked = horas_checked + valorhoras;
        console.log("horas checked 2:", valorhoras);  // Add this line to check the value
    } else {
        document.getElementById("diarias_martes").value = "";
    }
    if (c3 == true) {
        document.getElementById("diarias_miercoles").value = valorhoras
        horas_checked = horas_checked + valorhoras;
        console.log("horas checked 3:", valorhoras);  // Add this line to check the value
    } else {
        document.getElementById("diarias_miercoles").value = "";
    }
    if (c4 == true) {
        document.getElementById("diarias_jueves").value = valorhoras
        horas_checked = horas_checked + valorhoras;
        console.log("horas checked 4:", valorhoras);  // Add this line to check the value
    } else {
        document.getElementById("diarias_jueves").value = "";
    }
    if (c5 == true) {
        document.getElementById("diarias_viernes").value = valorhoras
        horas_checked = horas_checked + valorhoras;
        console.log("horas checked 5:", valorhoras);  // Add this line to check the value
    } else {
        document.getElementById("diarias_viernes").value = "";
    }
    if (c6 == true) {
        document.getElementById("diarias_sabado").value = valorhoras
        horas_checked = horas_checked + valorhoras;
        console.log("horas checked 6:", valorhoras);  // Add this line to check the value

    } else {
        document.getElementById("diarias_sabado").value = "";
    }
    if (c7 == true) {
        document.getElementById("diarias_domingo").value = valorhoras
        horas_checked = horas_checked + valorhoras;
        console.log("horas checked 7:", valorhoras);  // Add this line to check the value
    } else {
        document.getElementById("diarias_domingo").value = "";
    }
    var diferencia = horas - horas_checked;

    console.log("diferencia:" + diferencia);  // Add this line to check the value

    var mensaje = "Las horas semanales no cuadran con las horas diarias con una diferencia de " + diferencia + " frente a las horas semanales";

    if (diferencia !== 0) {
        showDialog(mensaje);
    }
}


/**
 * Funcion crear reglas de seguimiento
 *
 */
function crearReglaSeguimiento(menu_opcion, submenu_opcion, reglas_tipos) {
    var id = "";
    var url = "";
    var alias = "";
    var action = "crear";
    var ajax = objetoAjax();
    if (reglas_tipos == 3) {
        id = document.getElementById("id_tipo_productivo_empresa").value;
        alias = document.getElementById("alias_seguimiento_empresa").value;
    }
    url = "../common/ordenar_json_reglas_seguimiento.php?url=" + url + "&id_tipo_productivo=" + id + "&alias=" + alias + "&action=" + action;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                var html_txt = ajax.responseText;
                console.log(ajax.responseText);
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                        return;
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        if (jsonData.estado == 0) {
                            showDialog(jsonData.mensaje);
                            irAContenido(menu_activo, menu_opcion, submenu_opcion);
                            console.log(jsonData);
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404, 1);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status, 1);
            }
        }
    };
    ajax.send(null);
}

