/**
 * 
 * Funcion para guardar los elementos del calendario sin salir
 *
 */
function guardaElementosPlano(menu_opcion, submenu_opcion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var formulario = document.getElementById("nuevo_elemento");
        var longitudFormulario = formulario.elements.length;
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        for (var i = 0; i <= (longitudFormulario - 1); i++) {
            if (formulario.elements[i].required == true && formulario.elements[i].value == "") {
                showDialog(mensaje_faltan_campos, 1);
                formulario.elements[i].classList.add("requerido");
                return false;
            }
            if (formulario.elements[i].type != 'file' && formulario.elements[i].value != '') {
                formData.append(formulario.elements[i].name, formulario.elements[i].value);
            } else if (formulario.elements[i].value != '') {
                var files = formulario.elements[i].files;
                formData.append(formulario.elements[i].name, files[0], files[0].name);
            }
        }

        var url = "";
        var ajax = objetoAjax();;
        url = "../common/save_elements_plane.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            showDialog(arr_aux[1]);

                            //irAContenido(menu_activo,menu_opcion,submenu_opcion);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}



function validaCamposCiclo() {
    const nombre = document.getElementById("nombre_ciclo");
    const horario = document.getElementById("horario_ciclo");
    const dias = document.getElementById("dias_ciclo");
    const primerDia = document.getElementById("primer_dia_ciclo");
    const empleados = document.getElementById("empleados_ciclo");

    if (nombre.value.length <= 0) {
        throw new Error('Debe darle un nombre al ciclo');
    }
    if (horario.value <= -1) {
        throw new Error('Debe seleccionar un horario');
    }
    if (dias.value.length <= 0) {
        throw new Error('Debe colocar la cantidad de días del ciclo');
    } else if (dias.value < 7 || dias.value >= 100) {
        dias.value = 7;
    }
    if (primerDia.value <= -1) {
        throw new Error('Debe seleccionar un primer día');
    }
    if (empleados.value.length <= 0) {
        throw new Error('Debe colocar la cantidad de empleados del ciclo');
    } else if (empleados.value <= 0 || empleados.value >= 100) {
        throw new Error('La cantidad de empleados para el ciclo debe ser mayor a 0 y menor que 100');
    }
    return {
        nombre: nombre.value,
        horario: horario.value,
        dias: dias.value,
        primerDia: primerDia.value,
        empleados: empleados.value
    }
}



function siguiente_pantalla(elemento_id) {
    let campos = null;
    try {
        campos = validaCamposCiclo();
    } catch (err) {
        return;
    }

    clearTimeout(storedTimer);
    storedTimer = setTimeout(function (elemento_id, campos) {
        const ciclo_id = document.getElementById('ciclo_id');
        var url = "";
        var ajax = objetoAjax();
        if (ciclo_id == "") {
            url = "../common/crea_ciclos.php?hor_id=" + campos.horario + "&primer_dia=" + campos.primerDia + "&dc=" + campos.dias + "&ec=" + campos.empleados + "&eid=" + elemento_id;
        } else {
            url = "../common/crea_ciclos.php?hor_id=" + campos.horario + "&primer_dia=" + campos.primerDia + "&dc=" + campos.dias + "&ec=" + campos.empleados + "&eid=" + elemento_id + "&ciclo_id=" + ciclo_id.value;
        }
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            var jsonData = JSON.parse(arr_aux[1]);
                            //insertamos el cuadro
                            var tabla = document.getElementById("armar_ciclos");
                            tabla.innerHTML = jsonData.ciclo;
                            tabla.style.display = "flex";
                        }
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    }.bind(null, elemento_id, campos), 500);
}

function guarda_ciclo(menu_id, elemento_id, flag_edicion) {
    try {
        const campos = validaCamposCiclo();
    } catch (err) {
        showDialog(err.message);
        return;
    }
    var estado = document.getElementById("horario_ciclo");
    var horario_id = estado.options[estado.selectedIndex].value;
    var dia = document.getElementById("primer_dia_ciclo");
    var primer_dia = dia.options[dia.selectedIndex].value;
    var dias_ciclo = document.getElementById("dias_ciclo").value;
    var empleados_ciclo = document.getElementById("empleados_ciclo").value;
    var nombre_ciclo = document.getElementById("nombre_ciclo").value;
    var ciclo_id = document.getElementById("ciclo_id").value;
    var cuadrante = {};
    for (var k = 1; k <= empleados_ciclo; k++) {
        cuadrante[k] = {};
        for (var i = 1; i <= dias_ciclo; i++) {
            cuadrante[k][i] = 0;
            var radios = document.getElementsByName('turno_' + k + '_' + i);

            for (j = 0; j < radios.length; j++) {
                if (radios[j].checked) {
                    cuadrante[k][i] = radios[j].value;
                }
            }
        }
    }
    cuadrante = JSON.stringify(cuadrante);
    if (ciclo_id == "") {
        var datos = {
            "op": menu_id,
            "sub": elemento_id,
            "fe": flag_edicion,
            "nombre_ciclo": nombre_ciclo,
            "horario_id": horario_id,
            "dias_ciclo": dias_ciclo,
            "primer_dia": primer_dia,
            "empleados_ciclo": empleados_ciclo,
            "cuadrante": cuadrante
        }
    } else {
        var datos = {
            "op": menu_id,
            "sub": elemento_id,
            "fe": flag_edicion,
            "nombre_ciclo": nombre_ciclo,
            "horario_id": horario_id,
            "dias_ciclo": dias_ciclo,
            "primer_dia": primer_dia,
            "empleados_ciclo": empleados_ciclo,
            "cuadrante": cuadrante,
            "ciclo_id": ciclo_id
        }
    }
    var url = "";
    url = "../common/grabar_ciclo.php";
    esperaRespuesta(true);
    $.post(url, datos, function (data) {
        esperaRespuesta(false);
        var arr_aux = data.split("|");
        if (arr_aux[0] == 0) {
            showDialog(arr_aux[1]);
        }
        irAContenido(menu_activo, menu_id, elemento_id);
    });
}

function reduce_centros(elemento_id) {
    var ciclos = document.getElementById("id_ciclo");
    var ciclo_id = ciclos.options[ciclos.selectedIndex].value;
    var datos = {
        "ciclo_id": ciclo_id,
        "elemento_id": elemento_id
    }

    var url = "../common/reduce_departamentos.php";
    esperaRespuesta(true);
    $.post(url, datos, function (data) {
        esperaRespuesta(false);
        if (data != "") {
            var jsonData = JSON.parse(data);
            if (jsonData.estado == "ok") {
                document.getElementById("div_centros_turnos").classList.add("flex", "w-[25%]", "input_group", "mt-[-10px]", "justify-between");
                document.getElementById("div_centros_turnos").innerHTML = jsonData.centro;
                document.getElementById("div_centros_turnos").style.display = "flex";

                document.getElementById("div_departamentos_turnos").classList.add("filtros", "flex", "w-[25%]", "selector_form", "ml-2", "p-0", "mt-0", "relative");
                document.getElementById("div_departamentos_turnos").innerHTML = jsonData.depto;
                document.getElementById("div_departamentos_turnos").style.display = "flex";

                document.getElementById("div_empleados_turnos").classList.add("filtros", "flex", "w-[25%]", "selector_form", "ml-2", "p-0", "mt-0", "relative");
                document.getElementById("div_empleados_turnos").innerHTML = jsonData.empleado;
                document.getElementById("div_empleados_turnos").style.display = "flex";

                $(function () {
                    $("#departamentos").pqSelect({
                        multiplePlaceholder: seleccionar_departamento,
                        displayText: mensaje_filtro_seleccionados,
                        deselect: true,
                        selectallText: seleccionar_todos,
                        checkbox: true,
                        maxDisplay: 0,
                        search: true
                    }).on("change", function (evt) {
                        var val = $(this).val();
                        //console.log(val);
                        $("#departamento_ids").val(val);
                        reduce_empleados(elemento_id, val);
                    });
                });
                $(function () {
                    $("#empleados").pqSelect({
                        multiplePlaceholder: seleccionar_empleado,
                        displayText: mensaje_filtro_seleccionados,
                        deselect: true,
                        selectallText: seleccionar_todos,
                        checkbox: true,
                        maxDisplay: 0,
                        search: true
                    }).on("change", function (evt) {
                        var val = $(this).val();
                        $("#empleado_ids").val(val);
                    });
                });
            }
        }

    });

}

function reduce_empleados(elemento_id, departamentos) {

    if (departamentos === null) {
        reduce_centros(elemento_id);
    } else {
        var datos = {
            "depo_ids": departamentos,
            "elemento_id": elemento_id
        }
        var url = "";
        url = "../common/reduce_empleados.php";
        esperaRespuesta(true);
        $.post(url, datos, function (data) {
            esperaRespuesta(false);
            if (data != "") {
                var jsonData = JSON.parse(data);
                if (jsonData.estado == "ok") {
                    document.getElementById("div_empleados_turnos").classList.add("filtros", "flex", "w-[25%]", "selector_form", "ml-2", "p-0", "mt-0", "relative");
                    document.getElementById("div_empleados_turnos").innerHTML = jsonData.selector;
                    document.getElementById("div_empleados_turnos").style.display = "flex";
                    $(function () {
                        $("#empleados").pqSelect({
                            multiplePlaceholder: seleccionar_empleado,
                            displayText: mensaje_filtro_seleccionados,
                            deselect: true,
                            selectallText: seleccionar_todos,
                            checkbox: true,
                            maxDisplay: 0,
                            search: true
                        }).on("change", function (evt) {
                            var val = $(this).val();
                            $("#empleado_ids").val(val);
                        });
                    });
                }
            }
        });
    }
}

function valida_continuar_turnos(seccion_id, elemento_id, id) {
    var nombre_turno = document.getElementById("nombre_turno").value;
    var estado = document.getElementById("ciclo");
    var ciclo_id = estado.options[estado.selectedIndex].value;
    var fecha_inicio = document.getElementById("fecha_inicial").value;
    var fecha_final = document.getElementById("fecha_final").value;

    var error = 0;
    var errores = '';

    if (nombre_turno.length == 0) {
        error = 1;
        errores += '- Debe darle un nombre al turno<br>';
    }
    if (ciclo_id == -1) {
        error = 1;
        errores += '- Debe seleccionar un ciclo<br>';
    } else {
        var departamento_ids = document.getElementById("departamento_ids").value;
        var empleado_ids = document.getElementById("empleado_ids").value;
        if (empleado_ids.length == 0 && departamento_ids == 0) {
            error = 1;
            errores += '- Debe seleccionar al menos un empleado o un departamento del selector<br>';
        }
    }
    if (fecha_inicio.length == 0) {
        error = 1;
        errores += '- Debe seleccionar una fecha de inicio<br>';
    }
    if (fecha_final.length == 0) {
        error = 1;
        errores += '- Debe seleccionar una fecha de fin<br>';
    }
    const fi = new Date(fecha_inicio);
    const ff = new Date(fecha_final);
    if (fecha_inicio.length != 0 && fecha_final.length != 0 && fi > ff) {
        error = 1;
        errores += '- La fecha inicio no puede ser mayor que fecha fin<br>';
    }
    var fecha_actual = Date.now();
    if (fecha_inicio.length != 0 && fi < fecha_actual) {
        error = 1;
        errores += '- La fecha inicio no puede ser menor que la fecha actual<br>';
    }
    if (error == 0) {
        if (seccion_id == 0) {
            checkNone();
            siguiente_pantalla_turnos(elemento_id);
        } else {
            aplicar_planes_turnos(seccion_id, elemento_id, true, id);
        }
    } else if (error == 1) {
        showDialog(errores);
    }
}

/**
 * 
 * Funcion para captar el puesto
 *
 */
function setFechaTicketsPedidos(seccion_id, elemento_id, informe_id) {
    //inicializamos
    var date = "";
    var url = "";
    var ajax = objetoAjax();
    date = document.getElementById("fecha_fin").value;
    url = "../common/get_fecha_pedidos.php?date=" + date;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var jsonData = JSON.parse(html_txt);
                    if (jsonData.estado == 1) {
                        showDialog(jsonData.mensaje);
                        return;
                    } else if (jsonData.estado == 2) {
                        showDialog(jsonData.mensaje);
                        flag_echar = true;
                    } else {
                        //recargo la pagina
                        if (seccion_id > 0 && elemento_id > 0 && informe_id) {
                            verElemento(seccion_id, elemento_id, informe_id);
                            document.getElementById("fecha_fin").value = jsonData.final_date;
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404, 1);
            }
        }
    };
    ajax.send(null);
    esperaRespuesta(true);
}

