function crearFormTrabajo(menu_opcion, submenu_opcion, id, trabajo_id, datos_e_id, empleado_id) {
    var formTrab = new FormData();
    var blob_contenido = "";
    var id_elem = id;
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        formTrab.append('op', menu_opcion);
        formTrab.append('sub', submenu_opcion);
        var evidencia_id = id.replace('btn-', 'evidencia-');
        var item_elemento = document.getElementById(evidencia_id);
        var inputs = item_elemento.getElementsByTagName('input');
        var textarea = item_elemento.getElementsByTagName('textarea');
        var tzoffset = (new Date()).getTimezoneOffset() * 60000; //offset in milliseconds
        var fechaRealizado = new Date(new Date(Date.now() - tzoffset)).toISOString().slice(0, 19).replace('T', ' ');
        var null_date = new Date(0).toISOString().slice(0, 19).replace('T', ' ');
        for (var i = 0; i < inputs.length; i++) {
            if (item_elemento.classList.contains("imagen")) {
                formTrab.append('id_tipo_evidencia', 3);
                if (inputs[i].name == "imagen") {
                    formTrab.append('tipo_dato', "imagen");
                    formTrab.append('nombre_fichero', inputs[i].files[0].name);
                    formTrab.append('fecha_fichero', fechaRealizado);
                    formTrab.append('tipo_fichero', inputs[i].files[0].type);
                } else {
                    if (inputs[i].value != "") {
                        formTrab.append('contenido', inputs[i].value);
                    }


                }
                if (textarea[0].value != "") {
                    formTrab.append('id_trabajo', trabajo_id);
                    formTrab.append('id_datos_tipo_trabajo', datos_e_id);
                    formTrab.append('fecha_realizado', fechaRealizado);
                    formTrab.append('desc_evidencia', textarea[0].value);
                    formTrab.append('id_empleado', empleado_id);
                    formTrab.append('flag_terminado', 1);
                }
            }
            if (item_elemento.classList.contains("firma")) {
                formTrab.append('id_tipo_evidencia', 2);
                if (inputs[i].name == "firma") {
                    var canvas = document.getElementById("signature-pad");
                    var dataImage = canvas.toDataURL();
                    formTrab.append('data_image', dataImage);
                    formTrab.append('tipo_dato', "firma");
                    formTrab.append('nombre_fichero', (inputs[i].value).concat("_" + trabajo_id));
                    formTrab.append('fecha_fichero', fechaRealizado);
                    formTrab.append('tipo_fichero', 'image/png');
                    formTrab.append('contenido', null);
                }

                formTrab.append('id_trabajo', trabajo_id);
                formTrab.append('id_datos_tipo_trabajo', datos_e_id);
                formTrab.append('fecha_realizado', fechaRealizado);
                formTrab.append('desc_evidencia', textarea[0].value);
                formTrab.append('id_empleado', empleado_id);
                formTrab.append('flag_terminado', 1);

            }

        }
        if (item_elemento.classList.contains('texto')) {
            formTrab.append('id_tipo_evidencia', 4);
            if (textarea[0].value != "") {
                formTrab.append('id_trabajo', trabajo_id);
                formTrab.append('id_datos_tipo_trabajo', datos_e_id);
                formTrab.append('fecha_realizado', fechaRealizado);
                formTrab.append('desc_evidencia', textarea[0].value);
                formTrab.append('id_empleado', empleado_id);
                formTrab.append('flag_terminado', 1);
            }
        }
        if (id_elem == 'inicio' || id_elem == 'fin') {
            formTrab.append('id_tipo_evidencia', 1);
            if (id_elem == 'inicio') {
                formTrab.append('fichaje_inicio', fechaRealizado);
            } else {
                if (id_elem == 'fin') {
                    formTrab.append('fichaje_fin', fechaRealizado);
                }
            }
            formTrab.append('id_trabajo', trabajo_id);
            formTrab.append('id_datos_tipo_trabajo', datos_e_id);
            formTrab.append('fecha_realizado', fechaRealizado);
            formTrab.append('desc_evidencia', id_elem);
            formTrab.append('id_empleado', empleado_id);
            formTrab.append('flag_terminado', 1);
        }
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/save_evidencia.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            rellenaTrabajo(menu_opcion, submenu_opcion, trabajo_id);
                            showDialog(arr_aux[1]);
                        }
                    } else {
                        showDialog("No se han encontrado resultados con los parametros introducidos");
                    }
                } else if (ajax.status == 404) {
                    showDialog("La pagina no existe", 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(formTrab);
        esperaRespuesta(true);
    } else {
        showDialog("No es una opción válida");
    }
}
