//funciones nuevo modulo cursos
//añadir Alumno
function addAlumno(id) {
    var lista_alumnos_con = document.getElementById("lista-alumnos-con");
    disableAddAlumno(id);
    var idDelete = id.replace('btn-add-a-', '');
    var p_elemento_alumno = document.getElementById("p-a-" + idDelete);
    var string_p = p_elemento_alumno.innerHTML;
    var array_p = string_p.split(", ");
    var divA = document.createElement("div");
    var atrib = document.createAttribute("class");
    atrib.value = "elemento-lista";
    divA.setAttributeNode(atrib);
    atrib = document.createAttribute("id");
    atrib.value = "alumno-" + idDelete;
    divA.setAttributeNode(atrib);
    var iH = document.createElement("input");
    atrib = document.createAttribute("name");
    atrib.value = "alumno-" + idDelete;
    iH.setAttributeNode(atrib);
    atrib = document.createAttribute("type");
    atrib.value = "hidden";
    iH.setAttributeNode(atrib);
    atrib = document.createAttribute("value");
    atrib.value = idDelete;
    iH.setAttributeNode(atrib);
    var pA = document.createElement("p");
    var textoA = document.createTextNode(array_p[0] + ", " + array_p[1] + ", " + array_p[2]);
    pA.appendChild(textoA);
    var bA = document.createElement("div");
    atrib = document.createAttribute("class");
    atrib.value = "lista-boton";
    bA.setAttributeNode(atrib);
    atrib = document.createAttribute("id");
    atrib.value = "btn-delete-a-" + idDelete;
    bA.setAttributeNode(atrib);
    bA.setAttribute('onclick', 'deleteAlumno(' + idDelete + ');');
    textoA = document.createTextNode("Eliminar");
    bA.appendChild(textoA);
    lista_alumnos_con.appendChild(divA);
    divA.appendChild(iH);
    divA.appendChild(pA);
    divA.appendChild(bA);
}

