//filtrar alumno
function filtraAlumnos() {
    var inputValue = document.getElementById("filtroAlumno").value;
    if (inputValue != "") {
        var arrayDivNombreFiltrar = document.getElementById("lista-alumnos-sin").getElementsByClassName("elemento-lista-visible");
        var arrayPFiltrar = [];
        var arrayNombreFiltrar = [];
        for (i = 0; i < arrayDivNombreFiltrar.length; i++) {
            arrayPFiltrar.push(arrayDivNombreFiltrar[i].getElementsByTagName("p"));
        }
        for (i = 0; i < arrayPFiltrar.length; i++) {
            arrayNombreFiltrar.push(arrayPFiltrar[i][0].innerText);
        }
        for (i = 0; i < arrayNombreFiltrar.length; i++) {
            if (arrayNombreFiltrar[i].includes(inputValue) != true) {
                arrayPFiltrar[i][0].parentNode.classList.add('busqueda-filtro');
            }
        }
    } else {
        var arrayDivNombreFiltrar = document.getElementById("lista-alumnos-sin").getElementsByClassName("elemento-lista");
        for (i = 0; i < arrayDivNombreFiltrar.length; i++) {
            arrayDivNombreFiltrar[i].classList.remove('busqueda-filtro');
        }
    }

}
