/**
 * Funcion que guarda la configuración de la frecuencia con la que se pide el reconocimiento facial para un grupo de empleados
 */
function guardaConfRecFacial(menu_opcion, submenu_opcion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var checkboxes = document.getElementsByName('id');
        var empleados = [];
        for (var checkbox of checkboxes) {
            if (checkbox.checked) {
                empleados.push(checkbox.value);
            }
        }

        if (empleados.length <= 0) {
            showDialog(mensaje_faltan_campos, 1);
            return false;
        }

        var datos = {};

        var configuracion = document.getElementById('reconocimiento_facial_conf').value;

        if (configuracion == "" || configuracion == null || configuracion == undefined) {
            showDialog(mensaje_faltan_campos, 1);
            return false;
        } else {
            datos['reconocimiento_facial_conf'] = configuracion;
        }

        if (configuracion == 1) {
            var dias = document.getElementById('dias_conf_rec_facial').value;
            var tiempo = document.getElementById('tiempo_requerimiento').value;
            if (dias <= 0 || dias > 365) {
                if (tiempo == null || tiempo == "" || tiempo == "00:00") {
                    showDialog(mensaje_faltan_campos, 1);
                    return false;
                }
            }
        }

        if (dias != "" && dias != null && dias != undefined) {
            datos['dias_conf_rec_facial'] = dias;
        }
        if (tiempo != "" && tiempo != null && tiempo != undefined) {
            datos['tiempo_requerimiento'] = tiempo;
        }

        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        formData.append('empleados', empleados);
        formData.append('datos', JSON.stringify(datos));

        var url = "";
        var ajax = objetoAjax();;
        url = "../common/update_empleados_grupo.php";
        ajax.open("POST", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            showDialog(arr_aux[1]);
                            limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}



