function guardaPuestosEvaluacion(menu_opcion, submenu_opcion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var formulario = document.getElementById("nuevo_elemento");
        var longitudFormulario = formulario.elements.length;
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        var re = /^\w+$/;
        //var re2 = /(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).{6,}/;
        for (var i = 0; i <= (longitudFormulario - 1); i++) {
            if (formulario.elements[i].required == true && formulario.elements[i].value == "") {
                showDialog(mensaje_faltan_campos, 1);
                formulario.elements[i].classList.add("requerido");
                return false;
            } else if (formulario.elements[i].name == "name" && !re.test(formulario.elements[i].value)) {
                showDialog(formulario.elements[i].name + mensaje_error_caracteres);
                return false;
            }
            if (formulario.elements[i].type != 'file') {
                if (formulario.elements[i].type == "checkbox") {
                    if (formulario.elements[i].checked == true) {
                        formData.append(formulario.elements[i].name, formulario.elements[i].value);
                    }
                } else {
                    formData.append(formulario.elements[i].name, formulario.elements[i].value);
                }
            } else if (formulario.elements[i].value != '') {
                var files = formulario.elements[i].files;
                formData.append(formulario.elements[i].name, files[0], files[0].name);
            }
        }
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/save_elem.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            nuevoElemento(menu_opcion, submenu_opcion);
                            showDialog(arr_aux[1]);
                        }
                    } else {
                        showDialog("No se han encontrado resultados con los parametros introducidos");
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

function actualizarFormProcesos(select) {
    var selectedOption = select.options[select.selectedIndex];
    var indexSelected = selectedOption.dataset.metodo;
    var divs = document.getElementsByClassName("metodos");
    for (var i = 0; i < divs.length; i++) {
        const arrayMetodos = divs[i].dataset.menus.split("-");
        //   console.log(selectedOption);
        //   console.log(indexSelected);
        //   console.log(divs);
        //   console.log(arrayMetodos);
        if (arrayMetodos.indexOf(indexSelected) !== -1) { // se debe validar si la opción existe en el array
            var div = divs[i];
            if (div.classList.contains("metodos-visible")) {
                div.classList.toggle("metodos-visible");
                div.classList.toggle("metodos-ocultos");
            }
            div.classList.toggle("metodos-ocultos");
            div.classList.toggle("metodos-visible");
        } else {
            var div = divs[i];
            div.classList.remove("metodos-visible");
            div.classList.add("metodos-ocultos");
        }
    }
}

function addPregunta() {
    const cont = document.getElementsByClassName("grupo_preguntas").length;
    const form = document.getElementById("preguntas");

    const buttonBorrar = document.createElement("div");
    buttonBorrar.className = 'buttonBorrarPregunta cursor-pointer text-center p-2 rounded-full border border-solid border-[#2C2554] hover:bg-white text-sm font-medium hover:text-[#2C2554] bg-[#2C2554] text-[#FFFFFF]';
    buttonBorrar.id = `botonBorrar${cont}`;
    buttonBorrar.textContent = "Borrar";
    buttonBorrar.addEventListener('click', () => borrarPregunta(buttonBorrar));

    const divE = createItemElement("Texto de la Pregunta", "force input_label_form", "textarea", "texto_pregunta" + cont, "texto_pregunta" + cont, true, 10, 40);

    divE.appendChild(buttonBorrar);

    form.appendChild(divE);
}

function borrarPregunta(boton) {
    var elem = document.getElementById(boton.id);
    var elementoBorrar = elem.parentNode;
    elementoBorrar.remove();
}
function createItemElement(labelText, labelClass, inputType, inputName, inputId, inputRequired, rows = 0, cols = 0, type = "", min = 0, max = 0) {
    const divE = document.createElement("div");
    divE.className = "grupo_preguntas w-[25%] input_group mt-[-10px] px-2 flex justify-between";

    const label = document.createElement("label");
    label.className = labelClass;
    label.textContent = labelText;
    divE.appendChild(label);

    const input = document.createElement("input");
    input.className = 'w-full input_field h-[26px]';
    input.name = inputName;
    input.id = inputId;
    input.required = inputRequired;
    input.type = inputType;
    if (rows !== 0) input.rows = rows;
    if (cols !== 0) input.cols = cols;
    if (type !== "") input.type = type;
    if (min !== 0) input.min = min;
    if (max !== 0) input.max = max;

    divE.appendChild(input);
    return divE;
}

