/**
 * Funcion que gestiona la impresion de listados o informes
 *
 */
function imprimir_import_detalle(menu_opcion, submenu_opcion, tipo, accion, idElemento) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && !isNaN(tipo)) {
        var informesForm = document.getElementById("ver_elemento");
        var formData = new FormData();
        var id = 0;
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        formData.append('tipo', tipo);
        formData.append('accion', accion);
        if (idElemento != null && !isNaN(idElemento)) {
            formData.append('id_elementos', idElemento);
        }
        var idEmpleados = document.getElementById("id");
        if (idEmpleados != null) {
            formData.append('id_empleados', idEmpleados.value);
        }
        var listaEmpleados = document.getElementById("lista_empleados");
        if (listaEmpleados != null) {
            formData.append('lista_empleados', listaEmpleados.value);
        }
        var idEncuestas = document.getElementById('id_lista');
        if (idEncuestas != null) {
            formData.append('id_lista', idEncuestas.value);
        }
        var fechaInicio = document.getElementById("fecha_inicio");
        if (fechaInicio != null) {
            formData.append('fecha_inicio', fechaInicio.value);
        }
        var fechaFin = document.getElementById("fecha_fin");
        if (fechaFin != null) {
            formData.append('fecha_fin', fechaFin.value);
        }
        if (idSeleccionadas.length > 0) {
            formData.append('ids_seleccionados', idSeleccionadas);
            idSeleccionadas = new Array();
        }

        if (informesForm != null) {
            var longitudFormulario = informesForm.elements.length;
            var arrPlanes = new Array();
            var arrCentros = new Array();
            for (var i = 0; i <= (longitudFormulario - 1); i++) {

                prueba = informesForm.elements[i].id;
                if (informesForm.elements[i].required == true && informesForm.elements[i].value == "") {
                    showDialog(mensaje_faltan_campos, 1);
                    informesForm.elements[i].classList.add("requerido");
                    return false;
                }
                if (informesForm.elements[i].name == "plan_id") {
                    if (informesForm.elements[i].checked == true) {
                        arrPlanes.push(informesForm[i].value);
                    }
                } else if (informesForm.elements[i].name == "centro_id") {
                    if (informesForm.elements[i].checked == true) {
                        arrCentros.push(informesForm[i].value);
                    }
                } else if (informesForm.elements[i].name == "departamentos") {
                    formData.append(informesForm.elements[i].name, informesForm.elements[i].value);
                } else if (informesForm.elements[i].name == "centros") {
                    formData.append(informesForm.elements[i].name, informesForm.elements[i].value);
                } else if (informesForm.elements[i].name == "id_centros") {
                    formData.append(informesForm.elements[i].name, informesForm.elements[i].value);
                } else if (informesForm.elements[i].name == "empresas") {
                    formData.append(informesForm.elements[i].name, informesForm.elements[i].value);
                } else if (informesForm.elements[i].name == "id") {
                    id = informesForm.elements[i].value;
                    formData.append(informesForm.elements[i].name, informesForm.elements[i].value);
                } else if (informesForm.elements[i].name == "flag_aceptados" || informesForm.elements[i].name == "segundo_responsable") {
                    if (informesForm.elements[i].checked == true) {
                        formData.append(informesForm.elements[i].name, 1);
                    } else {
                        formData.append(informesForm.elements[i].name, 0);
                    }
                } else if (informesForm.elements[i].name == "activa_p_m" || informesForm.elements[i].name == "activa_sindical") {
                    if (informesForm.elements[i].checked == true) {
                        formData.append(informesForm.elements[i].name, 1);
                    } else {
                        formData.append(informesForm.elements[i].name, 0);
                    }
                } else if (informesForm.elements[i].name.indexOf('flag_') > -1) {
                    //Flag de campo en listado de empleados
                    if (informesForm.elements[i].checked == true) {
                        formData.append(informesForm.elements[i].name, 1);
                    }
                } else {
                    formData.append(informesForm.elements[i].id, informesForm.elements[i].value);
                }
            }
            if (arrPlanes.length > 0) {
                formData.append('planes', arrPlanes.join());
            }
            if (arrCentros.length > 0) {
                formData.append('centros', arrCentros.join());
            }
        }
        var url = "";
        var ajax = objetoAjax();
        url = "../common/print_plan_detalle.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    informeProcess = 0;
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            var jsonData = JSON.parse(arr_aux[1]);
                            showDialog(jsonData.mensaje);
                            // showDialog(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else if (arr_aux[0] == 3) {
                            if (id < informeEvaluacionEncuestas) {
                                window.open(arr_aux[1]);
                                irAContenido(menu_activo, menu_opcion, submenu_opcion);
                            } else {
                                // document.getElementById("content").innerHTML = arr_aux[1];

                                if (arr_aux[2] === undefined) {
                                    document.getElementById("content").innerHTML = arr_aux[1];
                                } else {
                                    document.getElementById("content").innerHTML = arr_aux[1];
                                    //console.log(arr_aux[1]);                                  
                                    $("#acordeon").accordion({
                                        heightStyle: "content",
                                        collapsible: true,
                                        active: parseInt(arr_aux[2])
                                    });
                                }
                            }
                        } else if (arr_aux[0] == 4) {
                            showDialog(arr_aux[1]);
                        } else {
                            var jsonData = JSON.parse(arr_aux[1]);
                            if (jsonData.mensaje == null) {
                                if (tipo == printPDF) {
                                    var arrDocumentos = jsonData.arr_html;
                                    var arrNombres = jsonData.arr_nombres;
                                    var arrOrientacion = jsonData.arr_orientacion;
                                    var flagPDF = false;
                                    paginasImpresion = arrNombres.length;
                                    if (arrNombres.length > 1) {
                                        //if(confirm("Se van a generar " + arrNombres.length + " archivos para completar la tarea\nno cierre la ventana hasta que hayan concluido todos")){
                                        showConfirm("Se van a generar " + arrNombres.length + " archivos para completar la tarea\nno cierre la ventana hasta que hayan concluido todos",
                                            crearPDF,
                                            arrDocumentos,
                                            arrNombres,
                                            arrOrientacion);
                                        //flagPDF =true;
                                        //}
                                    } else {
                                        crearPDF(arrDocumentos, arrNombres, arrOrientacion);
                                    }
                                } else if (tipo == printExcel) {
                                    window.open(jsonData.enlace);
                                } else if (tipo == printExportaExcel) {
                                    window.open(jsonData.enlace);
                                } else if (tipo == printScreen) {
                                    window.open(jsonData.enlace);
                                } else if (tipo == printVacacionesDevengadas) {
                                    window.open(jsonData.enlace);
                                } else if (tipo == printTicketsAcumRestaurant) {
                                    window.open(jsonData.enlace);
                                } else if (tipo == printTXT) {
                                    var arrDocumentos = jsonData.arr_txt;
                                    var arrNombres = jsonData.arr_nombres;
                                    var flagPDF = false;
                                    paginasImpresion = arrNombres.length;
                                    if (arrNombres.length > 1) {
                                        //if(confirm("Se van a generar " + arrNombres.length + " archivos para completar la tarea\nno cierre la ventana hasta que hayan concluido todos")){
                                        showConfirm("Se van a generar " + arrNombres.length + " archivos para completar la tarea\nno cierre la ventana hasta que hayan concluido todos",
                                            crearTXT,
                                            arrDocumentos,
                                            arrNombres);
                                        //flagPDF =true;
                                        //}
                                    } else {
                                        crearTXT(arrDocumentos, arrNombres);
                                    }
                                }
                            } else {
                                showDialog(jsonData.mensaje);
                            }
                            /*if(accion == accionLista){
                                irAContenido(menu_activo,menu_opcion,submenu_opcion);
                            }else if(accion == accionFormulario){
                                nuevoElemento(menu_opcion,submenu_opcion,null);
                            }else if(accion == accionEdicion){
                                var elementoId = arr_aux[1];
                                editaElemento(menu_opcion,submenu_opcion,elementoId);
                            }else if(accion == accionVista){
                                var elementoId = 0;
                                if(document.getElementById("id") != null){
                                    elementoId = document.getElementById("id").value;
                                }
                                verElemento(menu_opcion,submenu_opcion,elementoId);
                            }*/
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status == 500) {
                    showDialog("El tamaño de los datos manejados es muy grande,\nreduciendo busqueda a la última semana");
                    setLastWeek(menu_opcion, submenu_opcion);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                    esperaRespuesta(false);
                }
            }
        };
        ajax.send(formData);
        esperaRespuesta(true);
        informeProcess = 1;
    } else {
        showDialog(invalidOption);
    }

}
/**
 * Funcion que llama al procesamiento de una importacion
 *
 */
function procesaImportacionDetalle(menu_opcion, submenu_opcion, accion) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var formulario = document.getElementById("importar_elemento");
        var longitudFormulario = formulario.elements.length;
        var formData = new FormData();
        formData.append('op', menu_opcion);
        formData.append('sub', submenu_opcion);
        for (var i = 0; i <= (longitudFormulario - 1); i++) {
            if (formulario.elements[i].name == 'archivo') {
                if (formulario.elements[i].type == 'file' && formulario.elements[i].value != '') {
                    var files = formulario.elements[i].files;
                    formData.append(formulario.elements[i].name, files[0], files[0].name);
                } else {
                    showDialog(mensaje_error_no_archivo);
                    return false;
                }
            } else if (formulario.elements[i].name == 'plan_propio' && formulario.elements[i].checked == true) {
                formData.append('plan_propio', formulario.elements[i].value);
            } else if (formulario.elements[i].name == 'flag_lite' && formulario.elements[i].checked == true) {
                formData.append('flag_lite', formulario.elements[i].value);
            }
        }
        if (accion != null && !isNaN(accion)) {
            formData.append('accion', accion);
        }
        var url = "";
        var ajax = objetoAjax();;
        url = "../common/process_import_detalle.php";
        ajax.open("POST", url, true);
        //ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    informeProcess = 0;
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else {
                            var jsonData = JSON.parse(arr_aux[1]);
                            if (jsonData.enlace != null) {
                                window.open(jsonData.enlace);
                            }
                            if (jsonData.errores != null) {
                                window.open(jsonData.errores);
                            }
                            if (jsonData.mensaje != null) {
                                showDialog(jsonData.mensaje);
                            }
                            if (jsonData.error != null) {
                                showDialog(jsonData.error);
                            }
                            esperaRespuesta(true);
                            setTimeout(irAContenido, 5000, menu_activo, menu_opcion, submenu_opcion);
                            //irAContenido(menu_activo,menu_opcion,submenu_opcion);
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        informeProcess = 1;
        ajax.send(formData);
        esperaRespuesta(true);
    } else {
        showDialog(invalidOption);
    }
}

/**
 * Funcion que chequea que el dia y solo debe habilitado los lunes de cada semana
 *
 */
function my_check(in_date) {
    if (in_date.getDay() != 1) {
        return [false, "", 'Not Available'];
    } else {
        return [true, "", "Available"];
    }
}

