/**Funcion para calcular nota de evaluacion segun nota maxima ingresada */
function calculanotaplaneval() {
    var notabase = 20;
    var cantidad = $('#tablacuerpo')[0].children.length;
    var maximaponderacion = 25;
    var minimoponderacion = 5;

    for (i = 0; i < cantidad; i++) {

        var porcentaje = $('#tablacuerpo')[0].children[i].children[4].children[0].value;

        if (porcentaje > maximaponderacion) {
            var porcentaje = $('#tablacuerpo')[0].children[i].children[4].children[0].value = maximaponderacion;
        }

        if (porcentaje < minimoponderacion) {
            var porcentaje = $('#tablacuerpo')[0].children[i].children[4].children[0].value = minimoponderacion;
        }

        var n = notabase * porcentaje;
        var valor = n / 100;
        if (valor < 10) {
            valor = '0' + valor;
        }
        $('#tablacuerpo')[0].children[i].children[5].textContent = valor;

    }
}

