/**
 * Funcion que setea la fecha y hora para mostrar Presentes
 *
 */
function BusquedaComedor(menu_opcion, submenu_opcion, accion) {

    var url = "";
    var ajax = objetoAjax();;
    url = "../common/set_filtro_comedor.php";
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] == 1) {
                        showDialog(arr_aux[1]);
                    } else if (arr_aux[0] == 2) {
                        showDialog(arr_aux[1]);
                        flag_echar = true;
                    } else {
                        if (accion == accionLista) {
                            irAContenido(menu_activo, menu_opcion, submenu_opcion);
                        } else if (accion == accionFormulario) {
                            nuevoElemento(menu_opcion, submenu_opcion, null);
                        } else if (accion == accionEdicion) {
                            var elementoId = arr_aux[1];
                            editaElemento(menu_opcion, submenu_opcion, elementoId);
                        } else if (accion == accionVista) {
                            var elementoId = 0;
                            if (document.getElementById("id") != null) {
                                elementoId = document.getElementById("id").value;
                            }
                            verElemento(menu_opcion, submenu_opcion, elementoId);
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            }
            else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    ajax.send(null);
}

