function guardaResolcionCuestionario(menu_opcion, submenu_opcion, flag_mobil) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        var formulario = document.getElementById("nuevo_elemento");
        var longitudFormulario = formulario.elements.length;
        var formData = new FormData();
        var jsonObj = {};
        var flagSeleccionadas = false;

        if (flag_mobil == undefined || flag_mobil == 0) {
            formData.append('op', menu_opcion);
            formData.append('sub', submenu_opcion);
        } else {
            jsonObj.op = menu_opcion;
            jsonObj.sub = submenu_opcion;
        }
        var re = /^\w+$/;
        var re2 = /(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).{6,}/;
        var arrRadios = new Array();
        var arrRadiosChecked = new Array();
        var arrRadiosNoChecked = new Array();
        var arrCheckedRadios = new Array();
        var notificar = false;
        for (var i = 0; i <= (longitudFormulario - 1); i++) {
            if (formulario.elements[i].required == true && formulario.elements[i].type == "radio") {
                if (arrRadios.indexOf(formulario.elements[i].name) < 0) {
                    arrRadios.push(formulario.elements[i].name);
                    arrCheckedRadios.push(0);
                }
                if (formulario.elements[i].checked == true) {
                    arrCheckedRadios[arrRadios.indexOf(formulario.elements[i].name)] = 1;
                    arrRadiosChecked.push(formulario.elements[i].name);
                    if (flag_mobil == undefined || flag_mobil == 0) {
                        formData.append(formulario.elements[i].name, formulario.elements[i].value);
                    } else if (formulario.elements[i].name != "") {
                        jsonObj[formulario.elements[i].name] = formulario.elements[i].value;
                    }
                }
            } else if (formulario.elements[i].type == "hidden") {
                if (flag_mobil == undefined || flag_mobil == 0) {
                    formData.append(formulario.elements[i].name, formulario.elements[i].value);
                } else if (formulario.elements[i].name != "") {
                    jsonObj[formulario.elements[i].name] = formulario.elements[i].value;
                }
            }
        }
        showConfirm(guardar_cuestionario, enviarFormCuestionario, menu_opcion, submenu_opcion, flag_mobil, formData)

    } else {
        showDialog(invalidOption);
    }
}


function enviarFormCuestionario(menu_opcion, submenu_opcion, flag_mobil, formData) {
    var url = "";
    var ajax = objetoAjax();
    url = "../common/save_resolucion_cuestionario.php";
    ajax.open("POST", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                informeProcess = 0;
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] == 1) {
                        showDialog(arr_aux[1]);
                        return;
                    } else if (arr_aux[0] == 2) {
                        showDialog(arr_aux[1]);
                        return;
                        flag_echar = true;
                    } else {
                        showDialog(arr_aux[1]);
                        irAContenido(menu_activo, menu_opcion, submenu_opcion);
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404, 1);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status, 1);
            }
        }
    };
    informeProcess = 1;
    if (flag_mobil == undefined || flag_mobil == 0) {
        ajax.send(formData);
    } else {
        ajax.send(JSON.stringify(jsonObj));
    }
    esperaRespuesta(true);
}

