/**
 * Funciones para la exportacion de 2 o mas tablas a excel para el Datatables
 */

function getHeaderNames(table) {
    // Obtener nombre de cabecera .
    //params:
    //  table: table ID.
    //Returns:
    //  Array de columnas con el nombre de las cabeceras.

    var header = $(table).DataTable().columns().header().toArray();

    var names = [];
    header.forEach(function (th) {
        names.push($(th).html());
    });

    return names;
}

function getTableData(table, title) {
    // Procesa los datos de fila de Datatable para crear una hoja.
    //Params:
    //  table: table ID.
    //  title: Título que se muestra en la parte superior,  o un string vacío sin título.
    //Returns:
    //  Cadena de hoja de cálculo con formato XML.

    var header = getHeaderNames(table);
    var table = $(table).DataTable();
    var rowNum = 1;
    var mergeCells = '';
    var ws = '';

    ws += buildCols(header);
    ws += '<sheetData>';

    if (title.length > 0) {
        ws += buildRow([title], rowNum, 51);
        rowNum++;

        mergeCol = ((header.length - 1) + 10).toString(36).toUpperCase();

        mergeCells = '<mergeCells count="1">' +
            '<mergeCell ref="A1:' + mergeCol + '1"/>' +
            '</mergeCells>';
    }

    ws += buildRow(header, rowNum, 2);
    rowNum++;

    // agregar las filas a la hoja excel.    
    table.rows().every(function (rowIdx, tableLoop, rowLoop) {
        var data = this.data();

        // Si los datos están basados ​​en objetos, es necesario convertirlos
        // a un array antes de enviar a buildRow()
        ws += buildRow(data, rowNum, '');

        rowNum++;
    });

    ws += '</sheetData>' + mergeCells;

    return ws;

}

function buildCols(data) {
    // Construir columnas XML.
    //To do: define anchos para cada columna.
    //Params:
    //  data: row data.
    //Returns:
    //  String del XML con los anchos de columna formateados.

    var cols = '<cols>';

    for (i = 0; i < data.length; i++) {
        colNum = i + 1;
        cols += '<col min="' + colNum + '" max="' + colNum + '" width="20" customWidth="1"/>';
    }

    cols += '</cols>';

    return cols;
}

function buildRow(data, rowNum, styleNum) {
    // Construir row XML.
    //Params:
    //  data: Row data.
    //  rowNum: Excel numero de filas.
    //  styleNum: número de estilo o cadena vacía sin estilo
    //Returns:
    //  String de XML con las columnas de columna formateados.

    var style = styleNum ? ' s="' + styleNum + '"' : '';

    var row = '<row r="' + rowNum + '">';

    for (i = 0; i < data.length; i++) {
        colNum = (i + 10).toString(36).toUpperCase();  // Convert to alpha

        var cr = colNum + rowNum;

        row += '<c t="inlineStr" r="' + cr + '"' + style + '>' +
            '<is>' +
            '<t>' + data[i] + '</t>' +
            '</is>' +
            '</c>';
    }

    row += '</row>';

    return row;
}

function addSheet(xlsx, table, title, name, sheetId) {
    //Clona la hoja de la Hoja1 para construir una nueva hoja.
    //Params:
    //  xlsx: xlsx object.
    //  table: table ID.
    //  title: Título para la fila superior o en blanco si no hay título.
    //  name: Nombre de la nueva hoja.
    //  sheetId:cadena que contiene sheetId para la nueva hoja.
    //Returns:
    // Objeto de hoja actualizado.

    //Agrega la segunda hoja a  [Content_Types].xml => <Types>
    //============================================
    var source = xlsx['[Content_Types].xml'].getElementsByTagName('Override')[1];
    var clone = source.cloneNode(true);
    clone.setAttribute('PartName', '/xl/worksheets/sheet2.xml');
    xlsx['[Content_Types].xml'].getElementsByTagName('Types')[0].appendChild(clone);

    //Agregar relación de hoja to xl/_rels/workbook.xml.rels => Relationships
    //=====================================================================
    var source = xlsx.xl._rels['workbook.xml.rels'].getElementsByTagName('Relationship')[0];
    var clone = source.cloneNode(true);
    clone.setAttribute('Id', 'rId3');
    clone.setAttribute('Target', 'worksheets/sheet2.xml');
    xlsx.xl._rels['workbook.xml.rels'].getElementsByTagName('Relationships')[0].appendChild(clone);

    //Añadir segunda hoja a xl/workbook.xml => <workbook><sheets>
    //=========================================================
    var source = xlsx.xl['workbook.xml'].getElementsByTagName('sheet')[0];
    var clone = source.cloneNode(true);
    clone.setAttribute('name', name);
    clone.setAttribute('sheetId', sheetId);
    clone.setAttribute('r:id', 'rId3');
    xlsx.xl['workbook.xml'].getElementsByTagName('sheets')[0].appendChild(clone);

    //Agregar hoja2.xml a xl/worksheets
    //===============================
    var newSheet = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>' +
        '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" xmlns:x14ac="http://schemas.microsoft.com/office/spreadsheetml/2009/9/ac" mc:Ignorable="x14ac">' +
        getTableData(table, title) +

        '</worksheet>';

    xlsx.xl.worksheets['sheet' + sheetId + '.xml'] = $.parseXML(newSheet);


}

