function rechargeFav(submenu,menu_opcion,submenu_opcion) {
    //iconos a insertar
    var quoteIconSolid = "<i class='bx bxs-bookmark'></i>";
    var quoteIcon = "<i class='bx bx-bookmark'></i>";
    //saber desde donde se esta añadiendo el favorito
    var element = submenu.parentNode;
    var idRef = element.parentNode.parentNode.id;
    var aSubmenu = element.querySelector("a");
    var dataSubmenu = aSubmenu.dataset.submenu;
    var clonElement = element.cloneNode(true);
    clonElement.classList.add("text-[#707070]");
    var widgetBodyFav = document.getElementById("cardWidgetBodyFavoritos");
    var widgetFav = document.getElementById("cardWidgetFavoritos");
    var widgetFavEmpty = document.getElementById("cardWidgetFavoritosEmpty");
    //diferenciar si el click fue desde favorito o desde otro menu
    if (idRef == "Favoritos") {
        //busco el origen del submenu para cambiar el icono y borro el submenu de favoritos
        element.style.display = "none";
        var idOrigen = element.dataset.modulo;
        var divFav = document.getElementById(idOrigen);
        var ulFav = divFav.querySelector("ul");
        var listSubmenu = ulFav.querySelectorAll("li");
        for (var i = listSubmenu.length - 1; i >= 0; i--) {
            const dSubM = listSubmenu[i].querySelector("a").dataset.submenu;
            if (dataSubmenu === dSubM) {
                const divIcon = listSubmenu[i].querySelector("div");
                const actualIcon = divIcon.querySelector("i");

                actualIcon.style.display = "none";
                divIcon.innerHTML = quoteIcon;
            }
        }
    } else {
        //cambio el icono y añado el submenu de favoritos
        var divIcon = element.querySelector("div");
        var actualIcon = divIcon.querySelector("i");
        if (actualIcon.classList.contains('bxs-bookmark') === false) {
            actualIcon.style.display = "none";
            divIcon.innerHTML = quoteIconSolid;
            divIcon.classList.add("text-[#707070]");
            var clonDivIcon = clonElement.querySelector("div");
            var clonActualIcon = clonDivIcon.querySelector("i");
            clonActualIcon.style.display = "none";
            clonDivIcon.innerHTML = quoteIconSolid;
            var divFav = document.getElementById("Favoritos");
            var ulFav = divFav.querySelector("ul");
            ulFav.appendChild(clonElement);
            if (widgetBodyFav) {
                var divFavWidget = document.createElement('div');
                divFavWidget.className = 'cardWidget_itemMenu cursor-pointer rounded-xl py-3 flex justify-between items-center bg-[#F7F7F7] hover:bg-[#FFFFFF] transition duration-300 ease-in-out';
                var divFavWidgetBody = document.createElement('div');
                divFavWidgetBody.className = 'w-[15%] flex justify-center items-center';

                var iElement = clonElement.querySelector('i').cloneNode(true); // Clonamos el elemento <i>
                var submenuName = clonElement.querySelector('a').dataset.submenu;
                divFavWidget.setAttribute('data-submenu', submenuName);
                var divFavWidgetBodyName = document.createElement('div');
                divFavWidgetBodyName.className = 'w-[85%]';

                var divFavWidgetName = document.createElement('div');
                divFavWidgetName.className = 'cursor-pointer';
                divFavWidgetName.innerHTML = submenuName;

                divFavWidgetBodyName.appendChild(divFavWidgetName);
                divFavWidgetBody.appendChild(iElement);
                divFavWidget.appendChild(divFavWidgetBody);
                divFavWidget.appendChild(divFavWidgetBodyName);

                if (!widgetFavEmpty) {
                    widgetFav.appendChild(divFavWidget);
                } else {
                    widgetFav = document.createElement('div');
                    widgetFav.id = 'cardWidgetFavoritos';
                    widgetFav.className = 'cardWidget_row flex w-full justify-center items-center flex-wrap gap-2 mt-2';
                    widgetFav.appendChild(divFavWidget); 
                    widgetBodyFav.innerHTML = ''; 
                    widgetBodyFav.appendChild(widgetFav);
                }

                widgetFav.onclick = function () {
                    irAContenido(this, menu_opcion, submenu_opcion);
                };
            }
        } else {
            actualIcon.style.display = "none";
            divIcon.innerHTML = quoteIcon;
            divIcon.classList.add("text-[#707070]");
            var idOrigen = element.dataset.modulo;
            var divFav = document.getElementById("Favoritos");
            var ulFav = divFav.querySelector("ul");
            var listSubmenu = ulFav.querySelectorAll("li");
            for (var i = listSubmenu.length - 1; i >= 0; i--) {
                const dSubM = listSubmenu[i].querySelector("a").dataset.submenu;
                if (dataSubmenu === dSubM) {
                    listSubmenu[i].style.display = "none";
                }
            }
            if (widgetBodyFav) {
                const items = document.querySelectorAll('.cardWidget_itemMenu');
                items.forEach((item) => {
                    if (dataSubmenu === item.dataset.submenu) {
                        item.style.display = "none";
                    }
                });
                const todosOcultos = Array.from(items).every(item => {
                return window.getComputedStyle(item).display === 'none';
                });

                if (todosOcultos) {
                    widgetBodyFav.innerHTML = ''; 
                    var divFavWidgetEmpty = document.createElement('div');
                    divFavWidgetEmpty.id = 'cardWidgetFavoritosEmpty';
                    divFavWidgetEmpty.className = 'flex justify-center items-center flex-col mt-5';
                    var imgEmpty = document.createElement('img');
                    imgEmpty.className = 'img_empty_states';
                    imgEmpty.src = '../images/widgets/sin_datos_widget_favoritos.svg';
                    var spanTitulo = document.createElement('span');
                    spanTitulo.className = 'text-[#625999] text-[18px]';
                    spanTitulo.innerHTML = sinDatos_widget_favoritos;
                    var spanText = document.createElement('span');
                    spanText.className = 'text-[#96939B] text-[15px] text-center';
                    spanText.innerHTML = sinDatos_subText_favoritos;
                    divFavWidgetEmpty.appendChild(imgEmpty);
                    divFavWidgetEmpty.appendChild(spanTitulo);
                    divFavWidgetEmpty.appendChild(spanText);
                    widgetBodyFav.appendChild(divFavWidgetEmpty);
                }
            }
        }
    }
}


