//Funcion para quitar el overlay del menu
document.addEventListener('click', function (e) {
    var div = document.getElementById('overlayMenu');
    if (div !== null) {
        if (div.contains(e.target)) {
            // El clic se hizo dentro del div
            var element = document.getElementById('overlayMenu');
            element.parentNode.removeChild(element);
            toggleMenu(moduloSeleccionado);
            $("#" + moduloSeleccionado).removeClass("block");
            $("#" + moduloSeleccionado).addClass("hidden");
        } else {
            var sidebarSubmenus = document.querySelectorAll('.sidebar-submenu');
            var allElementsNotBlocked = true;
            sidebarSubmenus.forEach((element) => {
                if (element.classList.contains('block')) {
                    allElementsNotBlocked = false;
                }
            });
            if (allElementsNotBlocked) {
                var element = document.getElementById('overlayMenu');
                element.parentNode.removeChild(element);

            }
        }
    }
    if (select !== null) {
        if (!select.contains(e.target)) {
            select.classList.remove('active');
            opciones.classList.remove('active');
        }
    }
});

