window.addEventListener('resize', function () {
    setTimeout(() => {
        // Selecciona todas las tablas con la clase específica
        var tables = document.querySelectorAll('table.tablaDatatable.dataTable');

        // Itera sobre cada tabla encontrada
        tables.forEach((table) => {
            // Selecciona las cabeceras (th) de cada tabla individualmente
            var thElements = table.querySelectorAll('thead th:not(.dtr-hidden)');
            var lastThElement = thElements[thElements.length - 1];

            // Aplica los estilos a las cabeceras excepto la última
            for (var i = 0; i < thElements.length - 1; i++) {
                thElements[i].style.borderTopRightRadius = '0';
            }

            // Aplica el estilo a la última cabecera si existe
            if (lastThElement !== undefined) {
                lastThElement.style.borderTopRightRadius = '10px';
            }
        });
    }, "100");

});

