/**
 * Actualiza la DropZone con un placeholder o una imagen.
 *
 */
function updateThumbnail(dropZoneElement, file) {
    let thumbnailElement = dropZoneElement.querySelector(".drop-zone__thumb");

    // First time - remove the prompt
    if (dropZoneElement.querySelector(".drop-zone__prompt")) {
        dropZoneElement.querySelector(".drop-zone__prompt").remove();
    }

    // First time - there is no thumbnail element, so lets create it
    if (!thumbnailElement) {
        thumbnailElement = document.createElement("div");
        thumbnailElement.classList.add("drop-zone__thumb");
        dropZoneElement.appendChild(thumbnailElement);
    }

    thumbnailElement.dataset.label = file.name;

    // Show thumbnail for image files
    if (file.type.startsWith("image/")) {
        const reader = new FileReader();

        reader.readAsDataURL(file);
        reader.onload = () => {
            thumbnailElement.style.backgroundImage = `url('${reader.result}')`;
        };
    } else {
        thumbnailElement.style.backgroundImage = null;
    }

    thumbnailElement.addEventListener("click", () => {
        thumbnailElement.remove(); // Elimina la miniatura
        const inputElement = dropZoneElement.querySelector(".drop-zone__input");
        if (inputElement) {
            inputElement.value = ""; // Limpia el valor del input
        }
        // Vuelve a mostrar el mensaje del prompt
        if (!dropZoneElement.querySelector(".drop-zone__prompt")) {
            const newPrompt = document.createElement("span");
            newPrompt.classList.add("drop-zone__prompt");
            newPrompt.textContent = "Suelte el archivo aquí o haga clic para cargarlo";
            dropZoneElement.appendChild(newPrompt);
        }
    });

}

function validarInputNumberNegativo(event) {
    var input = event.target;
    var value = input.value;
    if (value.includes('-')) {
        input.value = '0';
    } else {
        input.value = value.replace(/[^0-9]/g, '0');
    }
}

function CargarPuestosDisc(selectBox) {
    var sector_name = selectBox.options[selectBox.selectedIndex].value;
    var puestodiscSelector = document.getElementById('puesto_talent_disc');
    var texto = puestodiscSelector.options[0].text;
    puestodiscSelector.options.length = 0;
    puestodiscSelector.options[0] = new Option(texto, "");

    var Boton = document.getElementById('BtnEncuestaDISC');
    Boton.classList.add("border-[#6D6D6D]");
    Boton.classList.add("bg-[#6D6D6D]");
    Boton.classList.remove("border-[#2BD47D]");
    Boton.classList.remove("hover:bg-white");
    Boton.classList.remove("hover:text-[#2BD47D]");
    Boton.classList.remove("bg-[#2BD47D]");
    Boton.setAttribute("disabled", "");

    if (sector_name != "") {
        var url = "";
        var ajax = objetoAjax();
        url = "../common/recarga_puesto_disc.php?name=" + sector_name;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var jsonData = JSON.parse(html_txt);
                        if (jsonData.estado == 1) {
                            showDialog(jsonData.mensaje);
                        } else if (jsonData.estado == 2) {
                            showDialog(jsonData.mensaje);
                            flag_echar = true;
                        } else if (jsonData.estado == 0) {
                            var arr_puestos = jsonData.puestos;
                            var id_puestos = jsonData.id_puestos;
                            if (sector_name != null) {
                                for (var key in id_puestos) {
                                    if (id_puestos.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {
                                        puestodiscSelector.options[puestodiscSelector.options.length] = new Option(arr_puestos[key], id_puestos[key]);
                                    }
                                }
                            }
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                }
                else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(null);
    }
}


