function indexTourBienvenida() {
    const indiceActivo = $('.step-indicator_w.active').index();
    const totalIndicadores = $('.step-indicator_w').length - 1;
    $('.step-indicators_n').text(`${indiceActivo} de ${totalIndicadores}`);
}

$(document).ready(function () {
    $(".step-indicator_w").click(function () {
        const stepToShow = $(this).data("step");
        $(".tour-step").hide();
        $(stepToShow).show();
        $(".step-indicator_w.active").removeClass("active");
        $(this).addClass("active");
        indexTourBienvenida();
    });
    $("#prevStep").click(() => {
        const currentStep = $(".step-indicator_w.active").data("step");
        const prevStep = $(currentStep).prev(".tour-step").attr("id");
        if (prevStep) {
            $(".tour-step").hide();
            $("#" + prevStep).show();
            $(".step-indicator_w.active").removeClass("active");
            $(".step-indicator_w[data-step='#" + prevStep + "']").addClass("active");

            indexTourBienvenida();
        } else {
            const currentStep = $(".step-indicator_w.active").data("step");
            const prevStep = $(currentStep).nextAll(".tour-step").last().attr("id");
            $(".tour-step").hide();
            $("#" + prevStep).show();
            $(".step-indicator_w.active").removeClass("active");
            $(".step-indicator_w[data-step='#" + prevStep + "']").addClass("active");
            indexTourBienvenida();
        }
    });

    $("#nextStep").click(() => {
        const currentStep = $(".step-indicator_w.active").data("step");
        const nextStep = $(currentStep).next(".tour-step").attr("id");
        if (nextStep) {
            $(".tour-step").hide();
            $("#" + nextStep).show();
            $(".step-indicator_w.active").removeClass("active");
            $(".step-indicator_w[data-step='#" + nextStep + "']").addClass("active");
            indexTourBienvenida();
        } else {
            const currentStep = $(".step-indicator_w.active").data("step");
            const nextStep = $(currentStep).prevAll(".tour-step").last().attr("id");
            $(".tour-step").hide();
            $("#" + nextStep).show();
            $(".step-indicator_w.active").removeClass("active");
            $(".step-indicator_w[data-step='#" + nextStep + "']").addClass("active");
            indexTourBienvenida();
        }
    });
});



