function inputsPersonalizadosForm(count = 0) {
    setTimeout(function () {
        // Drag and Drop
        const inputSelector = `.drop-zone__input${count === 0 ? '' : '_' + count}`;
        const dropZoneSelector = `.drop-zone${count === 0 ? '' : '_' + count}`;

        document.querySelectorAll(inputSelector).forEach((inputElement) => {
            const dropZoneElement = inputElement.closest(dropZoneSelector);

            dropZoneElement.addEventListener("click", () => {
                inputElement.click();
            });

            inputElement.addEventListener("change", () => {
                if (inputElement.files.length) {
                    updateThumbnail(dropZoneElement, inputElement.files[0]);
                }
            });

            dropZoneElement.addEventListener("dragover", (e) => {
                e.preventDefault();
                dropZoneElement.classList.add("drop-zone--over");
            });

            ["dragleave", "dragend"].forEach((type) => {
                dropZoneElement.addEventListener(type, () => {
                    dropZoneElement.classList.remove("drop-zone--over");
                });
            });

            dropZoneElement.addEventListener("drop", (e) => {
                e.preventDefault();
                if (e.dataTransfer.files.length) {
                    inputElement.files = e.dataTransfer.files;
                    updateThumbnail(dropZoneElement, e.dataTransfer.files[0]);
                }
                dropZoneElement.classList.remove("drop-zone--over");
            });
        });

        //Editor WYSIWYG Quill 
        var editorConfig = {
            modules: {
                toolbar: [
                    ['bold', 'italic', 'underline'],        // toggled buttons
                    [{ 'list': 'ordered' }, { 'list': 'bullet' }],
                    [{ 'header': [1, 2, 3, 4, 5, 6, false] }],
                    [{ 'color': [] }, { 'background': [] }], // dropdown with defaults from theme
                    [{ 'align': [] }],
                ]
            },
            theme: 'snow',
        };

        if (document.getElementById('editorWYSIWYG') || document.getElementById('editormensajeria')) {
            quilljs_textarea('.quilljs-textarea', editorConfig);
        }
        $('#filtroNombre').on('input', function () {
            var filtro = $(this).val().toLowerCase();
            $('#tabla_horarios_permisos tbody tr').each(function () {
                var nombre = $(this).find('td:first').text().toLowerCase();
                if (nombre.indexOf(filtro) !== -1) {
                    $(this).show();
                } else {
                    $(this).hide();
                }
            });
        });
    }, 500);
}

