function createTable(titulo, dataObj, rangosColores, isDomainTable = false) {
    const tableContainer = document.createElement('div');
    tableContainer.className = 'mt-5';

    const title = document.createElement('h3');
    title.className = 'text-[20px] text-[#667185] font-medium mb-3 flex items-center';
    title.innerHTML = titulo;
    tableContainer.appendChild(title);

    const table = document.createElement('table');
    table.className = 'table-auto border-collapse border border-gray-300 w-full table-fixed';

    // Encabezado
    const thead = document.createElement('thead');
    thead.innerHTML = `
        <tr class="bg-gray-100 border border-solid border-[#DBDBDB]">
            <th class="border border-gray-300 px-2 py-2 w-1/2">${isDomainTable ? 'Dominio' : 'Categoría'}</th>
            <th class="border border-gray-300 px-2 py-2 w-1/2">Clasificación</th>
            <th class="border border-gray-300 px-2 py-2 w-1/4 text-center">Valor</th>
        </tr>`;
    table.appendChild(thead);

    // Cuerpo
    const tbody = document.createElement('tbody');
    for (const key in dataObj) {
        const subObj = dataObj[key];

        // Si es tabla de dominios, procesar sub-objetos
        if (isDomainTable && typeof subObj === 'object') {
            for (const subKey in subObj) {
                const puntaje = subObj[subKey];
                let color = "";
                let nombre = "";
                // Determinar color según el puntaje
                for (const rango in rangosColores) {
                    const { rango: limites, color: colorFondo } = rangosColores[rango];
                    const [min, max] = limites;
                    if (puntaje >= min && puntaje <= max) {
                        color = colorFondo;
                        nombre = rango;
                        break;
                    }
                }
                // Crear fila para el dominio
                const row = document.createElement('tr');
                row.className = 'hover:bg-gray-50 border border-solid border-[#DBDBDB]';

                row.innerHTML = `
                    <td class="border border-gray-300 px-2 py-2 text-sm text-[#344054]">${subKey}</td>
                    <td class="border border-gray-300 px-2 py-2 text-center text-sm text-[#222222]" ><span class="${color} py-1 px-2 rounded-full text-[#222222]">${nombre}</span></td>
                    <td class="border border-gray-300 px-2 py-2 text-center text-sm text-[#74828F]">${puntaje}</td>
                `;

                tbody.appendChild(row);
            }
        } else if (!isDomainTable) {
            // Si es tabla de categorías, procesar valores directamente
            const puntaje = subObj;
            let color = "";
            let nombre = "";
            // Determinar color según el puntaje
            for (const rango in rangosColores) {
                const { rango: limites, color: colorFondo } = rangosColores[rango];
                const [min, max] = limites;
                if (puntaje >= min && puntaje <= max) {
                    color = colorFondo;
                    nombre = rango;
                    break;
                }
            }

            // Crear fila para la categoría
            const row = document.createElement('tr');
            row.className = 'hover:bg-gray-50 border border-solid border-[#DBDBDB]';

            row.innerHTML = `
                <td class="border border-gray-300 px-2 py-2 text-sm text-[#344054]">${key}</td>
                <td class="border border-gray-300 px-2 py-2 text-center text-sm text-[#222222]"><span class="${color} py-1 px-2 rounded-full text-[#222222]">${nombre}</span></td>
                <td class="border border-gray-300 px-2 py-2 text-center text-sm text-[#74828F]">${puntaje}</td>
            `;

            tbody.appendChild(row);
        }
    }

    table.appendChild(tbody);
    tableContainer.appendChild(table);

    return tableContainer;
}

function createPuntajeFinalTable(puntajeFinal) {
    // Determinar la clasificación final y el color según el puntaje
    let clasificacionFinal = '';
    let colorFondo = '';
    if (puntajeFinal < 20) {
        clasificacionFinal = 'Nulo o Despreciable';
        colorFondo = 'bg-[#B0F0AA]';
    } else if (puntajeFinal >= 20 && puntajeFinal < 45) {
        clasificacionFinal = 'Bajo';
        colorFondo = 'bg-[#EFE163]';
    } else if (puntajeFinal >= 45 && puntajeFinal < 70) {
        clasificacionFinal = 'Medio';
        colorFondo = 'bg-[#FDBC44]';
    } else if (puntajeFinal >= 70 && puntajeFinal < 90) {
        clasificacionFinal = 'Alto';
        colorFondo = 'bg-[#FAB8B8]';
    } else if (puntajeFinal >= 90) {
        clasificacionFinal = 'Muy Alto';
        colorFondo = 'bg-[#FC7272]';
    }

    // Crear contenedor de tabla
    const tableContainer = document.createElement('div');
    var calificacionTitulo = `<span class="text-[#667185] text-[16px] font-semibold mr-2">Clasificación:</span> <span class="${colorFondo} py-1 px-2 rounded-full text-[#222222] text-[16px] mr-1">${clasificacionFinal}</span> <span class="text-[#667185] text-[16px] font-semibold"> /      Valor: ${puntajeFinal}</span>`;
    tableContainer.innerHTML = calificacionTitulo;
    /*const table = document.createElement('table');
    table.className = 'table-auto border-collapse border border-gray-300 w-full table-fixed';

    // Encabezado
    const thead = document.createElement('thead');
    thead.innerHTML = `
        <tr class="bg-gray-100 border border-solid border-[#DBDBDB]">
            <th class="border border-gray-300 px-2 py-2 w-1/2">Clasificación</th>
            <th class="border border-gray-300 px-2 py-2 w-1/2 text-center">Valor</th>
        </tr>`;
    table.appendChild(thead);

    // Cuerpo
    const tbody = document.createElement('tbody');
    const row = document.createElement('tr');

    row.innerHTML = `
        <td class="border border-gray-300 px-2 py-2 text-sm">${clasificacionFinal}</td>
        <td class="border border-gray-300 px-2 py-2 text-center text-sm ${colorFondo}">${puntajeFinal}</td>
    `;
    tbody.appendChild(row);

    table.appendChild(tbody);
    tableContainer.appendChild(table);*/

    return tableContainer;
}




function genContenidoDialogoResultadoNom35(jsonData, empresa) {
    const data = JSON.parse(jsonData);
    var nombreModal = data[0][0].nombre
    var apellidoModal = data[0][0].apellidos
    // Diccionario para los nombres según id_tipo
    const nombresPorTipo = {
        4: "I - Identificar a los Trabajadores que Fueron Sujetos a Acontecimientos Traumáticos Severos",
        5: "II - Recuerdos Persistentes sobre el Acontecimiento  /  III - Esfuerzo por Evitar Circunstancias Parecidas o Asociadas al Acontecimiento y IV - Afectación",
        6: "V - IDENTIFICACIÓN y Análisis de los Factores de RIESGO Psicosocial",
        7: "VI - Identificación y Análisis de los Factores de Riesgo Psicosocial y Evaluación del Entorno Organizacional en los Centros de Trabajo",

    };

    // Crear contenedor principal
    const container = document.createElement('div');
    container.className = 'w-full px-5 mt-5 mx-auto !w-[100%]';
    container.style.maxHeight = '85%';
    container.style.overflow = 'auto';

    // Rango de puntuaciones y colores
    const rangosColores = {
        "Nulo o Despreciable": { rango: [0, 5], color: "bg-[#B0F0AA]" },
        "Bajo": { rango: [6, 15], color: "bg-[#EFE163]" },
        "Medio": { rango: [16, 30], color: "bg-[#FDBC44]" },
        "Alto": { rango: [31, 50], color: "bg-[#FAB8B8]" },
        "Muy Alto": { rango: [51, Infinity], color: "bg-[#FC7272]" },
    };
    // Agregar título al centro según id_tipo

    const tituloEmpleado = document.createElement('h2');
    tituloEmpleado.className = 'text-center text-xl font-bold text-[#2C2554]';
    tituloEmpleado.innerText = nombreModal + ' ' + apellidoModal; // Manejo de id_tipo no definido
    const empresaEmpleado = document.createElement('h2');
    empresaEmpleado.className = 'text-center text-xl font-bold mb-5 text-[#2C2554]';
    empresaEmpleado.innerText = empresa;
    var sectionP = document.createElement('div');
    sectionP.appendChild(tituloEmpleado);
    sectionP.appendChild(empresaEmpleado);
    container.appendChild(sectionP);
    // Iterar sobre los datos
    data[0].forEach((item) => {
        const section = document.createElement('div');
        section.className = 'mb-5 border-b border-[#C7CAD2B8] border-solid';

        // Agregar título al centro según id_tipo
        const tituloTipo = document.createElement('h2');
        tituloTipo.className = 'text-start text-[18px] font-normal mb-5 text-[#412DB6]';
        tituloTipo.innerText = nombresPorTipo[item.id_tipo] || "Sin título definido"; // Manejo de id_tipo no definido
        section.appendChild(tituloTipo);

        if (item.json_respuestas !== null) {
            if (item.id_tipo == 6 || item.id_tipo == 7) {
                // Convertir los datos de resultados y respuestas a objetos
                const resultados = JSON.parse(item.resultado_nom35);

                // Crear contenedor para las tablas
                const contenedorTablas = document.createElement('div');
                contenedorTablas.className = 'flex gap-5 justify-center'; // Flexbox para alinear tablas horizontalmente con espacio entre ellas

                // Crear tabla de categorías
                const tablaCategorias = createTable(
                    "<i class='ti ti-folders text-[#412DB6] text-[25px] mr-1'></i> Puntajes por Categoría",
                    resultados.puntajes_categoria,
                    rangosColores
                );
                tablaCategorias.className += ' flex-1'; // Asegurar que las tablas ocupen espacio proporcional
                contenedorTablas.appendChild(tablaCategorias);

                // Crear tabla de dominios
                const tablaDominios = createTable(
                    "<i class='ti ti-scale text-[#412DB6] text-[25px] mr-1'></i> Puntajes por Dominio",
                    resultados.puntajes_dominio,
                    rangosColores,
                    true
                );
                tablaDominios.className += ' flex-1'; // Asegurar que las tablas ocupen espacio proporcional
                contenedorTablas.appendChild(tablaDominios);

                // Agregar contenedor de tablas a la sección
                section.appendChild(contenedorTablas);

                // Crear la leyenda debajo de las tablas
                const legend = document.createElement('p');
                legend.className = 'text-sm mt-3 text-gray-500 text-center bg-[#F3F4F6B5] flex items-center justify-center p-3';
                legend.innerHTML = `
                <div class="flex flex-wrap gap-2 text-sm text-[#344054]">
                    <div class="flex items-center gap-2">
                        <span>Leyenda de Clasificaciones por Color: </span>
                    </div>
                    <div class="flex items-center gap-2">
                        <div class="w-4 h-4 bg-[#B0F0AA] border border-green-400 rounded-full"></div>
                        <span>Nulo o Despreciable</span>
                    </div>
                    <div class="flex items-center gap-2">
                        <div class="w-4 h-4 bg-[#EFE163] border border-blue-400 rounded-full"></div>
                        <span>Bajo</span>
                    </div>
                    <div class="flex items-center gap-2">
                        <div class="w-4 h-4 bg-[#FDBC44] border border-yellow-400 rounded-full"></div>
                        <span>Medio</span>
                    </div>
                    <div class="flex items-center gap-2">
                        <div class="w-4 h-4 bg-[#FAB8B8] border border-orange-400 rounded-full"></div>
                        <span>Alto</span>
                    </div>
                    <div class="flex items-center gap-2">
                        <div class="w-4 h-4 bg-[#FC7272] border border-red-400 rounded-full"></div>
                        <span>Muy Alto</span>
                    </div>
                </div>
            `;


                // Agregar la leyenda debajo de las tablas
                section.appendChild(legend);

                // Mostrar puntaje final y clasificación final
                const resumen = document.createElement('div');
                resumen.className = 'my-5 text-center flex justify-center items-center';

                const puntajeFinal = document.createElement('p');
                puntajeFinal.className = 'text-[18px] text-[#412DB6] font-bold mr-2';
                puntajeFinal.innerText = `Puntaje Final`;


                resumen.appendChild(puntajeFinal);
                //  resumen.appendChild(clasificacionFinal);
                section.appendChild(resumen);
                // Mostrar puntaje final en formato de tabla
                const tablaPuntajeFinal = createPuntajeFinalTable(resultados.calificacion_final);
                resumen.appendChild(tablaPuntajeFinal);
            }

            if (item.id_tipo == 4) {
                const resultados = JSON.parse(item.resultado_nom35);
                const tablaMensaje = document.createElement('div');
                tablaMensaje.className = 'w-full text-start pb-5 ';
                //tablaMensaje.style.borderCollapse = 'collapse';

                //const filaMensaje = document.createElement('tr');
                const celdaMensaje = document.createElement('span');
                celdaMensaje.className = 'text-[16px] text-[#667185]';
                //celdaMensaje.colSpan = 1;
                celdaMensaje.innerText = (resultados == 'no') ? 'El Trabajador NO Requiere Una Valoración Clínica' : 'El Trabajador necesita contestar las otras secciones: II, III y IV para poder dar un resultado final';

                //filaMensaje.appendChild(celdaMensaje);
                tablaMensaje.appendChild(celdaMensaje);
                section.appendChild(tablaMensaje);


            }

            if (item.id_tipo == 5) {
                const resultados = JSON.parse(item.resultado_nom35);
                const tablaMensaje = document.createElement('div');
                tablaMensaje.className = 'w-full text-start pb-5 ';
                //tablaMensaje.style.borderCollapse = 'collapse';

                //const filaMensaje = document.createElement('tr');
                const celdaMensaje = document.createElement('span');
                celdaMensaje.className = 'text-[16px] text-[#667185]';
                //celdaMensaje.colSpan = 1;
                celdaMensaje.innerText = (resultados == 'no') ? 'El Trabajador NO Requiere Una Valoración Clínica' : 'El Trabajador Requiere Una Valoración Clínica';

                //filaMensaje.appendChild(celdaMensaje);
                tablaMensaje.appendChild(celdaMensaje);
                section.appendChild(tablaMensaje);
            }

        } else {
            // Mostrar mensaje de "No ha realizado la encuesta" en una tabla con fondo gris
            const tablaMensaje = document.createElement('table');
            tablaMensaje.className = 'w-full text-center bg-gray-200 rounded-lg';
            tablaMensaje.style.borderCollapse = 'collapse';

            const filaMensaje = document.createElement('tr');
            const celdaMensaje = document.createElement('td');
            celdaMensaje.className = 'py-5 text-lg font-bold text-gray-600';
            celdaMensaje.colSpan = 1;
            celdaMensaje.innerText = (item.porcentaje == 0) ? 'No ha realizado la encuesta' : 'Encuesta sin asignar';

            filaMensaje.appendChild(celdaMensaje);
            tablaMensaje.appendChild(filaMensaje);
            section.appendChild(tablaMensaje);
        }

        container.appendChild(section);
    });


    return container;
}


function ExportNom35Pdf() {
    esperaRespuesta(true);
    const botonExport = document.querySelector("#containerBotonPDF");
    botonExport.classList.add("!hidden");
    setTimeout(() => {
        const originalLineHeight = document.body.style.lineHeight;
        document.body.style.lineHeight = '0.5';
        const element = document.getElementById('openModalNom35');
        const { jsPDF } = window.jspdf;

        const originalOverflow = element.style.overflow;
        const originalHeight = element.style.height;
        const originalScrollTop = element.scrollTop;

        element.style.overflow = 'visible';
        element.style.height = 'auto';

        html2canvas(element, {
            scale: 2,
            useCORS: true,
        }).then((canvas) => {
            const pdf = new jsPDF('p', 'mm', 'a4');

            const imgData = canvas.toDataURL('image/png');
            const imgWidth = 210; // A4 en mm
            const imgHeight = (canvas.height * imgWidth) / canvas.width;

            let position = 0;
            if (imgHeight > 297) {
                while (position < imgHeight) {
                    pdf.addImage(imgData, 'PNG', 0, position > 0 ? 0 : 10, imgWidth, imgHeight);
                    position += 297;
                    if (position < imgHeight) pdf.addPage();
                }
            } else {
                pdf.addImage(imgData, 'PNG', 0, 10, imgWidth, imgHeight);
            }

            pdf.save('Nom35.pdf');
            esperaRespuesta(false);

            element.style.overflow = originalOverflow;
            element.style.height = originalHeight;
            element.scrollTop = originalScrollTop;
            botonExport.classList.remove("!hidden");
            document.body.style.lineHeight = originalLineHeight;
        }).catch((error) => {
            console.error('Error al generar el PDF:', error);

            element.style.overflow = originalOverflow;
            element.style.height = originalHeight;
            element.scrollTop = originalScrollTop;
            botonExport.classList.remove("!hidden");
            document.body.style.lineHeight = originalLineHeight;
            esperaRespuesta(false);
        });
    }, "500")

}












