function toggleMenuDesktop() {
    const sidebar = document.getElementById('sidebar_desktop');
    const isExpanded = sidebar.offsetWidth === 224;

    // Cambia el ancho de la sidebar
    sidebar.style.width = isExpanded ? '6em' : '16em';

    // Selecciona elementos relevantes
    const textMenu = document.querySelectorAll('.text-menu-icon');
    const iconoMenu = document.querySelectorAll('.icon-menu');
    const contenedorLogo = document.getElementById('logo_container');
    const body = document.querySelectorAll('.section-container');
    const titulo_sidebar = document.querySelectorAll('.titulo_sidebar');
    const pqselect = document.querySelectorAll('.pq-select-popup-cont');
    const pqselectFecha = document.getElementById('ui-datepicker-div');

    // Actualiza estilos según el estado
    textMenu.forEach(item => {
        item.style.display = isExpanded ? "none" : "block"; // Oculta o muestra texto
    });
    iconoMenu.forEach(item => {
        item.style.justifyContent = isExpanded ? 'center' : 'start'; // Ajusta alineación
    });
    contenedorLogo.style.flexDirection = isExpanded ? "column" : "row"; // Cambia dirección
    contenedorLogo.classList.toggle("p-[10px]", !isExpanded); // Añade o quita padding
    contenedorLogo.classList.toggle("pb-6", !isExpanded); // Añade o quita padding
    sidebar.classList.toggle("px-2", isExpanded); // Cambia padding
    sidebar.classList.toggle("px-4", !isExpanded);
    body.forEach(item => {
        item.style.left = isExpanded ? "84px" : "224px"; // Ajusta posición del cuerpo
        item.style.width = isExpanded ? "calc(100% - 84px)" : "calc(100% - 224px)"; // Ajusta tamaño del cuerpo
    });
    titulo_sidebar.forEach(item => {
        item.classList.toggle("justify-center", isExpanded); // centrar texto
    });
    pqselect.forEach(item => {
        item.style.transform = isExpanded ? "translate(-120px, 5px)" : "translate(-270px, 5px)"; // Ajusta posicion de los pqselect
    });
    pqselectFecha.style.transform = isExpanded ? "translate(-120px, 5px)" : "translate(-270px, 5px)"; // Ajusta posicion de los pqselect
}

