function gestionaCarrusel(menu_opcion, submenu_opcion, elementos, titulos = "") {
    var elementosArray = elementos.split(",");
    var titulosArray = titulos.split(",");

    // Crear un solo array de objetos con elemento y su título correspondiente
    var elementosUnidos = elementosArray.map((elemento, i) => ({
        elemento,
        titulo: titulosArray[i] || "" // Si no hay título correspondiente, asignar cadena vacía
    }));

    if (Array.isArray(elementosUnidos)) {
        var contenidos = [];
        var elementosProcesados = 0;

        elementosUnidos.forEach((item, i) => {
            setTimeout(() => {
                verInfoCarrusel(menu_opcion, submenu_opcion, item.elemento, function (contenido) {
                    contenidos[i] = contenido;
                    elementosProcesados++;
                    if (elementosProcesados === elementosUnidos.length) {
                        console.log(contenidos);
                        showDialogInfoCarrusel(contenidos);
                    }
                }, item.titulo);
            }, i * 1000); // Retraso de 1 segundo entre cada petición
        });
    } else {
        console.error("El tercer parámetro debe ser un array.");
    }
}

function verInfoCarrusel(menu_opcion, submenu_opcion, elemento_id, callback, titulo_evento) {
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion) && elemento_id != "") {
        var url = "../common/gen_view_elem.php?op=" + menu_opcion + "&sub=" + submenu_opcion + '&id=' + elemento_id + '&titulo=' + titulo_evento;
        var ajax = new XMLHttpRequest();
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            callback(arr_aux[1]);
                        } else if (arr_aux[0] == 2) {
                            callback(arr_aux[1]);
                            flag_echar = true;
                        } else {
                            if (arr_aux[2] === undefined) {
                                callback(arr_aux[1]);
                            } else {
                                callback(arr_aux[1]);
                            }
                        }
                    } else {
                        callback(noResults);
                    }
                } else if (ajax.status == 404) {
                    callback(error404);
                } else if (ajax.status != 0) {
                    callback("Error:" + ajax.status);
                }
            }
        };
        esperaRespuesta(true);
        ajax.send(null);
    } else {
        callback(invalidOption);
    }
}

function showDialogInfoCarrusel(contenidos) {
    var caja = document.getElementById('openModal');
    if (caja != null) {
        hideDialog();
        caja.appendChild(genContenidoDialogoInfoCarrusel(contenidos));
        caja.style.opacity = 1;
        caja.style.pointerEvents = "auto";
    }
}

function genContenidoDialogoInfoCarrusel(contenidos) {
    console.log(contenidos)
    var divElement = document.createElement('div');
    divElement.className = ' !w-full md:!w-[60%] !mt-[5%] !mx-auto flex flex-col bg-white rounded-lg p-5 shadow-lg relative';

    var anchorElement = document.createElement('div');
    anchorElement.innerHTML = '<i class="ti ti-x text-[#1C274C] font-bold text-[20px]"></i>';
    anchorElement.title = 'Close';
    anchorElement.id = 'botonPrincipal';
    anchorElement.className = 'absolute top-2 right-0 flex h-11 w-11 items-center justify-center rounded-full border border-solid border-[#D9D9D961] bg-[#D9D9D961] hover:bg-white mr-5 cursor-pointer';
    anchorElement.onclick = function () {
        hideDialog();
        if (flag_echar == true) {
            window.location = "../inc/salir.php";
            flag_echar = false;
        } else if (flag_recarga == true) {
            window.location.reload();
            flag_recarga = false;
        }
    };

    var divContent = document.createElement('div');
    divContent.id = 'containerTotal';
    divContent.className = 'w-full flex justify-center mb-5 flex-col text-center';

    var divButtons = document.createElement('div');
    divButtons.id = "containerButtons"
    divButtons.className = 'w-full flex justify-around';

    // Crear el carrusel
    var carousel = document.createElement('div');
    //carousel.className = 'carousel';
    carousel.id = 'containerCarousel';
    carousel.className = 'w-full flex justify-center';

    contenidos.forEach(function (texto, index) {
        var pElement = document.createElement('p');
        pElement.innerHTML = texto;
        var botonera = pElement.querySelector('.botonera');
        if (botonera) {
            botonera.style.display = 'none';
        }

        pElement.className = 'carousel-itemContenido';
        //pElement.className = 'w-full flex justify-center';
        if (index !== 0) {
            pElement.classList.add('hidden')
        }
        carousel.appendChild(pElement);
    });

    var prevButton = document.createElement('button');
    prevButton.className = 'prev';
    prevButton.innerHTML = '<';
    prevButton.onclick = function () {
        showCarouselItem(-1);
    };

    var nextButton = document.createElement('button');
    nextButton.className = 'next';
    nextButton.innerHTML = '>';
    nextButton.onclick = function () {
        showCarouselItem(1);
    };

    divButtons.appendChild(prevButton);
    divButtons.appendChild(nextButton);

    divContent.appendChild(carousel);
    divContent.appendChild(divButtons);
    divElement.appendChild(anchorElement);
    divElement.appendChild(divContent);

    return divElement;
}

function showCarouselItem(direction) {
    var items = document.querySelectorAll('.carousel-itemContenido');
    items[currentCarouselIndex].style.display = 'none';
    currentCarouselIndex = (currentCarouselIndex + direction + items.length) % items.length;
    items[currentCarouselIndex].style.display = 'block';
}

function redondearBordes() {
    // Selecciona todos los botones
    const botones = document.querySelectorAll('.redondearBordes');
    // Verifica si hay botones
    if (botones.length === 0) {
        return; // Salir de la función si no hay botones
    }
    // Limpia las clases de redondeo
    botones.forEach(boton => {
        boton.style.borderTopLeftRadius = '';
        boton.style.borderBottomLeftRadius = '';
        boton.style.borderTopRightRadius = '';
        boton.style.borderBottomRightRadius = '';
    });

    // Contar cuántos botones están visibles
    var visibleCount = 0;
    botones.forEach(boton => {
        if (boton.style.display !== 'none' && !boton.hidden) {
            visibleCount++;
        }
    });

    // Verifica si solo hay un botón visible
    if (visibleCount === 1) {
        // Aplica el borde redondeado al único botón visible
        botones.forEach(boton => {
            if (boton.style.display !== 'none' && !boton.hidden) {
                boton.style.borderTopLeftRadius = '9999px'; // Borde redondeado izquierdo
                boton.style.borderBottomLeftRadius = '9999px'; // Borde redondeado izquierdo
                boton.style.borderTopRightRadius = '9999px'; // Borde redondeado derecho
                boton.style.borderBottomRightRadius = '9999px'; // Borde redondeado derecho
            }
        });
    } else {
        // Verifica si el primer botón está oculto
        const primerBoton = botones[0];
        if (primerBoton.style.display === 'none' || primerBoton.hidden) {
            // Aplica el borde redondeado al segundo botón
            if (botones.length > 1) {
                botones[1].style.borderTopLeftRadius = '9999px'; // Segundo botón
                botones[1].style.borderBottomLeftRadius = '9999px'; // Segundo botón
            }
        } else {
            // Aplica el borde redondeado al primer y último botón
            if (botones.length > 0) {
                primerBoton.style.borderTopLeftRadius = '9999px'; // Primer botón
                primerBoton.style.borderBottomLeftRadius = '9999px'; // Primer botón
                const ultimoBoton = botones[botones.length - 1];
                if (ultimoBoton.style.display === 'none' || ultimoBoton.hidden) {
                    // Aplica el borde redondeado al penúltimo botón
                    if (botones.length > 1) {
                        botones[botones.length - 2].style.borderTopRightRadius = '9999px'; // Penúltimo botón
                        botones[botones.length - 2].style.borderBottomRightRadius = '9999px'; // Penúltimo botón
                    }
                } else {
                    // Aplica el borde redondeado al último botón
                    ultimoBoton.style.borderTopRightRadius = '9999px'; // Último botón
                    ultimoBoton.style.borderBottomRightRadius = '9999px'; // Último botón
                }
            }
        }
    }
}

function verPortada(origen, menu_opcion, submenu_opcion) {
    $("#buscadorDatatable").addClass("hidden");
    $("#Favoritos").addClass("hidden");
    if (!isNaN(menu_opcion) && menu_opcion > 0 && menu_opcion <= maxMenu && !isNaN(submenu_opcion)) {
        $('body').click(function (e) {
            e.preventDefault();
            e.stopImmediatePropagation(); //charles ma is right about that, but stopPropagation isn't also needed
        });
        if (!isNaN(origen)) {
            if (origen != menu_activo) {
                numeroPagina = 1;
                idSeleccionadas = new Array();
                origen.classList.add('current');
                if (submenu_activo != null) {
                    submenu_activo.classList.remove('current');
                }
                submenu_activo = origen;
            }
        }
        var url = "";
        var ajax = objetoAjax();
        url = "../common/gen_portada.php?op=" + menu_opcion + "&sub=" + submenu_opcion + "&pag=" + numeroPagina;
        ajax.open("GET", url, true);
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    if (paginasImpresion == 0) {
                        esperaRespuesta(false);
                    }
                    var html_txt = ajax.responseText;
                    if (html_txt != "") {
                        var arr_aux = html_txt.split("|");
                        if (arr_aux[0] == 1) {
                            showDialog(arr_aux[1], 1);
                        } else if (arr_aux[0] == 2) {
                            showDialog(arr_aux[1], 2);
                            flag_echar = true;
                        } else if (html_txt.indexOf("Fatal error") >= 0) {
                            showDialog(mensaje_error_tiempo_maximo_ejecucion);
                            limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
                        } else {
                            document.getElementById("content").innerHTML = arr_aux[1];
                        }
                    } else {
                        showDialog(noResults);
                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status == 500) {
                    showDialog(mensaje_error_tiempo_maximo_ejecucion);
                    limpiarFiltros(menu_opcion, submenu_opcion, accionLista, null);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        if (accionesEjecutando <= 0) {
            esperaRespuesta(true);
        }
        ajax.send(null);
    } else {
        showDialog(invalidOption);
    }
}

function btnDownload() {
    // Selecciona el nodo del DOM que deseas observar (en este caso, el body)
    const targetNode = document.body;

    // Configura el observer para observar cambios en el DOM
    const observer = new MutationObserver((mutationsList, observer) => {
        // Recorre las mutaciones detectadas
        for (const mutation of mutationsList) {
            // Verifica si existe un elemento con las clases .dataTables_wrapper .no-footer o .tabla_listado
            if (document.querySelector('.dataTables_wrapper .no-footer') || document.querySelector('.tabla_listado')) {
                // Si existe, quita la clase 'hidden' del elemento con ID 'downloadMobile'
                $("#downloadMobile").removeClass("hidden");
                // Detén el observer si ya no necesitas seguir observando
                observer.disconnect();
                break;
            }
        }
    });

    // Configuración del observer: observa cambios en los hijos y en el árbol del DOM
    const config = { childList: true, subtree: true };

    // Inicia el observer
    observer.observe(targetNode, config);
}

