function reloadEmpleadosByEmpresas(selectBox, menu_opcion, submenu_opcion) {
    if (selectBox != null) {
        var empresa_id = selectBox.options[selectBox.selectedIndex].value;
        if (document.getElementById("id_empleados") != null) {
            EmpleadosSelect = document.getElementById("id_empleados");
            texto = EmpleadosSelect.options[0].text;
            EmpleadosSelect.options.length = 0;
            EmpleadosSelect.options[0] = new Option(texto, "");
        }
        if (empresa_id != "") {
            var url = "";
            var ajax = objetoAjax();;
            url = "../common/recarga_empleados_empresas.php?id=" + empresa_id + "&op=" + menu_opcion + "&sub=" + submenu_opcion;
            ajax.open("GET", url, true);
            ajax.onreadystatechange = function () {
                if (ajax.readyState == 4) {
                    if (ajax.status == 200) {
                        esperaRespuesta(false);
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var jsonData = JSON.parse(html_txt);
                            if (jsonData.estado == 1) {
                                showDialog(jsonData.mensaje);
                            } else if (jsonData.estado == 2) {
                                showDialog(jsonData.mensaje);
                                flag_echar = true;
                            } else if (jsonData.estado == 0) {
                                var arr_empleados = jsonData.arr_empleados;
                                if (typeof EmpleadosSelect != "undefined") {
                                    for (var key in arr_empleados) {
                                        if (arr_empleados.hasOwnProperty(key) && /^0$|^[1-9]\d*$/.test(key) && key <= 4294967294) {
                                            EmpleadosSelect.options[EmpleadosSelect.options.length] = new Option(arr_empleados[key], key);
                                        }
                                    }
                                }
                            }
                        } else {
                            showDialog(noResults);
                        }
                    } else if (ajax.status == 404) {
                        showDialog(error404);
                    } else if (ajax.status != 0) {
                        showDialog("Error:" + ajax.status);
                    }
                }
            };
            esperaRespuesta(true);
            ajax.send(null);
        }
    } else {
        showDialog(invalidOption);
    }
}

function AddProdKpi(menu_opcion, submenu_opcion) {

    let nuevosBloques = document.querySelectorAll("[class^='Productos-']");
    let x_productos = 0;
    nuevosBloques.forEach((bloque, index) => {
        x_productos++;
    });

    let ultimoBloque = document.querySelector(`#ContenedorProdKpi .Productos-${x_productos - 1}`);

    if (x_productos > 0 && !validarSeleccion(ultimoBloque)) {
        return;
    }

    deshabilitarElementos(ultimoBloque);

    var url = "../common/get_info_objetivo_produccion.php?op=" + menu_opcion + "&sub=" + submenu_opcion;
    var ajax = new XMLHttpRequest();
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                esperaRespuesta(false);
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] == 1) {
                        showDialog(arr_aux[1]);
                    } else if (arr_aux[0] == 2) {
                        showDialog(arr_aux[1]);
                        flag_echar = true;
                    } else {
                        var response = JSON.parse(arr_aux[1]);
                        if (response.Productos.length > 0 || response.Kpi.length > 0) {
                            ConstruyeContenido(response);
                        } else {
                            showDialog("No hay productos ni KPIs disponibles.");
                        }
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404);
            } else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status);
            }
        }
    };
    esperaRespuesta(true);
    ajax.send(null);
}

function validarSeleccion(bloque) {
    if (!bloque) {
        showDialog("Error interno: No se encontró el último bloque.");
        return false;
    }

    // Validar producto seleccionado
    let productoSeleccionado = bloque.querySelector('.id_productos option:checked');
    if (!productoSeleccionado || productoSeleccionado.value === "") {
        showDialog("Debe seleccionar al menos un producto antes de agregar otro bloque.");
        return false;
    }

    // Validar al menos un KPI marcado
    let kpisSeleccionados = bloque.querySelectorAll('.id_kpi:checked');
    if (kpisSeleccionados.length === 0) {
        showDialog("Debe seleccionar al menos un KPI antes de agregar otro bloque.");
        return false;
    }

    // Validar que los KPIs marcados tengan un valor en el input de Meta
    for (let kpi of kpisSeleccionados) {
        let inputMeta = kpi.closest("tr").querySelector('input[name^="meta_kpi"]');
        if (!inputMeta || inputMeta.value.trim() === "") {
            showDialog("Debe ingresar una meta para cada KPI seleccionado.");
            return false;
        }
    }

    return true;
}

function deshabilitarElementos(bloque) {
    if (!bloque) return;

    // Deshabilitar selector de productos
    let selectorProducto = bloque.querySelector('.id_productos');
    if (selectorProducto) selectorProducto.setAttribute("disabled", "true");

    // Deshabilitar checkboxes de KPIs
    let checkboxesKpi = bloque.querySelectorAll('.id_kpi');
    checkboxesKpi.forEach(checkbox => checkbox.setAttribute("disabled", "true"));

    // Deshabilitar inputs de meta
    let inputsMeta = bloque.querySelectorAll('input[name^="meta_kpi"]');
    inputsMeta.forEach(input => input.setAttribute("disabled", "true"));
}

function toggleMetaInput(checkbox) {
    let metaInput = checkbox.closest('tr').querySelector('.meta_kpi');
    metaInput.disabled = !checkbox.checked;

    if (checkbox.checked) {
        metaInput.removeAttribute("disabled");
    } else {
        metaInput.setAttribute("disabled", "true");
        metaInput.value = "";
    }
}

function ConstruyeContenido(data) {
    let nuevosBloques = document.querySelectorAll("[class^='Productos-']");
    let x_productos = 0;
    nuevosBloques.forEach((bloque, index) => {
        x_productos++;
    });

    let productosSeleccionados = new Set(
        Array.from(document.querySelectorAll('.id_productos option:checked'))
            .map(option => option.value)
    );

    let productosDisponibles = data.Productos.filter(prod => !productosSeleccionados.has(prod.id));

    if (productosDisponibles.length === 0) {
        showDialog("No hay más productos disponibles.");
        return;
    }

    let productosOptions = productosDisponibles.map(prod =>
        `<option value="${prod.id}">${prod.keyword} - ${prod.nombre}</option>`
    ).join("");

    let kpiRows = data.Kpi.map(kpi => `
        <tr class="border-b border-gray-300 odd:bg-gray-100 even:bg-white">
            <td class="px-[1%] py-[.5%] w-[10%]">
                <label class="container_check ml-[10px] mt-[13px]">
                    <input type="checkbox" class="id_kpi" name="id_kpi[${x_productos}][]" value="${kpi.id}" onchange="toggleMetaInput(this);">
                    <span class="checkmark"></span>
                </label>
            </td>
            <td class="px-[1%] py-[.5%] w-[60%]">${kpi.nombre}</td>
            <td class="px-[1%] py-[.5%] w-[30%]">
                <input class="w-[90%] border-2 border-blue-500 rounded-md px-2 py-1 ring-2 ring-gray-300 focus:ring-blue-300 bg-white placeholder-gray-400 meta_kpi" type="text" maxlength="32" size="40" name="meta_kpi[${x_productos}][${kpi.id}]" value="" placeholder="Meta" disabled>
            </td>
        </tr>
    `).join("");

    let Contenido = `
    <div class="Productos-${x_productos} border-b border-[#D0D2DE] border-solid pb-2">
        <div class="flex w-full !mt-[2rem]">
            <div class="ml-2 w-[100%] input_group p-0">
                <span class="titulo_seleccionar">Relacion de Objetivo:</span>  
            </div>  
        </div>  
        <div class="flex w-full !mt-[2rem]">  
            <div class="selector_form ml-2 w-[30%] input_group p-0">  
                <label class="force input_label_form" for="id_productos">Productos<span class="force-red">*</span></label>  
                <select class="w-full id_productos" name="id_productos[${x_productos}]" required>  
                    <option value="" hidden>Seleccione Producto</option>  
                    ${productosOptions}  
                </select>  
            </div>  
            <div class="selector_form ml-2 w-[10%] input_group p-0 ">  
            </div>
            <div class="selector_form ml-2 w-[20%] input_group p-0 ">  
                <a data-id="${x_productos}" class="DelProdKpi hover:text-[#990000] hover:!bg-white text-sm py-2.5 px-5 rounded-full border border-2 border-solid border-[#990000] !bg-[#990000] text-[#FFFFFF]" onclick="javascript:DelProdKpi(${x_productos});">Eliminar Producto</a>
            </div>
        </div>  
        <div class="flex w-full !mt-[2rem]">  
            <div class="divDatatable tabla datatableContainer !h-[40vh]">  
                <div class="tabla_planilla_3-3 rounded-xl !border-0 !bg-white shadow-lg px-[0px] !my-0 !ml-0 !mr-[10px] !w-full">  
                    <div class="seleccionar">  
                        <span class="titulo_seleccionar">Kpis Aplicables:</span>  
                    </div>  
                    <table class="rounded-xl !border-0 !bg-white shadow-lg !m-0 !w-full">  
                        <thead class="bg-[#F9B226] !text-[#333333] !text-[16px]">  
                            <tr>  
                                <th class="px-[1%] py-[.75%] !font-thin w-[10%]">#&nbsp;</th>  
                                <th class="px-[1%] py-[.75%] !font-thin w-[60%]">Nombre </th>  
                                <th class="px-[1%] py-[.75%] !font-thin w-[30%]">Meta </th>  
                            </tr>  
                        </thead>  
                        <tbody>  
                            ${kpiRows}  
                        </tbody>  
                    </table>  
                </div>  
            </div>  
        </div>  
    </div>`;

    $('#ContenedorProdKpi').append(Contenido);

    x_productos++;
}

function DelProdKpi(id_producto) {
    // Eliminar el bloque correspondiente
    $(`.Productos-${id_producto}`).remove();

    // Reindexar todos los bloques restantes
    let nuevosBloques = document.querySelectorAll("[class^='Productos-']");
    x_productos = 0;
    nuevosBloques.forEach((bloque, index) => {
        let nuevoIndex = x_productos++;
        bloque.className = `Productos-${nuevoIndex} border-b border-[#D0D2DE] border-solid pb-2`;

        // Actualizar los atributos de los elementos dentro del bloque
        bloque.querySelector('.id_productos').name = `id_productos[${nuevoIndex}]`;
        bloque.querySelectorAll(".id_kpi").forEach(checkbox => {
            checkbox.name = `id_kpi[${nuevoIndex}][]`;
        });
        bloque.querySelectorAll(".meta_kpi").forEach(input => {
            input.name = `meta_kpi[${nuevoIndex}][]`;
        });

        // Actualizar el botón de eliminación con el nuevo index
        let deleteButton = bloque.querySelector(".DelProdKpi");
        if (deleteButton) {
            deleteButton.setAttribute("onclick", `javascript:DelProdKpi(${nuevoIndex});`);
            deleteButton.setAttribute("data-id", nuevoIndex);
        }
    });
}

