/**
 * Funcion que realiza un fichaje manual Quick
 *
 */
function fichajeManualQuick(menu_opcion, submenu_opcion, strFichaje, idGestionProyectos, checkUbicacion = false) {
    var jsonObj = {};
    jsonObj.op = menu_opcion;
    jsonObj.sub = submenu_opcion;
    jsonObj.tipo_incidencia = strFichaje;
    var infoAdicional = document.getElementById('informacion_adicional');
    if (infoAdicional != null) {
        jsonObj.informacion_adicional = infoAdicional.value;
    }
    var textoFichajeProyecto = document.getElementById('texto_fichaje_proyecto');
    if (textoFichajeProyecto != null) {
        jsonObj.informacion_adicional = textoFichajeProyecto.value;
    }
    if (idGestionProyectos != null) {
        jsonObj.id_gestion_proyectos = idGestionProyectos;
    }
    var lat_ob = document.getElementById('lat');
    if (lat_ob != undefined && lat_ob != null) {
        jsonObj.lat = document.getElementById('lat').value;
        jsonObj.lon = document.getElementById('lon').value;
    }

    var ordenTrabajo = document.getElementById('orden_trabajo');
    if (ordenTrabajo != null && ordenTrabajo.value != "") {
        jsonObj.orden_trabajo = ordenTrabajo.value;
    }
    var idTerminales = document.getElementById('id_terminales');
    if (idTerminales != null && idTerminales.options[idTerminales.selectedIndex].value != "") {
        jsonObj.id_terminales = idTerminales.options[idTerminales.selectedIndex].value;
    }
    var tarea = document.getElementById('tarea');
    if (tarea != null && tarea.options[tarea.selectedIndex].value != "") {
        jsonObj.tarea = tarea.options[tarea.selectedIndex].value;
    }
    var tarea_proyecto = document.getElementById('tarea_proyecto');
    var actividad = document.getElementById('actividad');
    if (tarea_proyecto != null && tarea_proyecto.options[tarea_proyecto.selectedIndex].value != "" &&
        actividad != null && actividad.options[actividad.selectedIndex].value != "") {
        jsonObj.tarea_proyecto = tarea_proyecto.options[tarea_proyecto.selectedIndex].value;
        jsonObj.actividad = actividad.options[actividad.selectedIndex].value;
    }
    const selectProyecto = document.getElementById('id_proyectos');
    const selectTarea = document.getElementById('id_tareas');
    if (selectProyecto != null && selectProyecto.options[selectProyecto.selectedIndex].value != ""
        && selectTarea != null && selectTarea.options[selectTarea.selectedIndex].value != "") {
        jsonObj.proyectoNew = selectProyecto.options[selectProyecto.selectedIndex].value;
        jsonObj.tareaNew = selectTarea.options[selectTarea.selectedIndex].value;
    }
    const fecha = document.getElementById('fecha');
    if (fecha != null && fecha.value != "") {
        jsonObj.fecha = fecha.value;
    }
    const hora = document.getElementById('hora');
    if (hora != null && hora.value != "") {
        jsonObj.hora = hora.value;
    }
    var idCentros = document.getElementById('id_centros');
    if (idCentros != null) {
        jsonObj.id_centros = idCentros.value;
    }
    var jornada_efectiva_horas = document.getElementById('quantity_horas');
    var jornada_efectiva_minutos = document.getElementById('quantity_minutos');
    if ((jornada_efectiva_horas != null) && (jornada_efectiva_minutos != null)) {
        jsonObj.jornada_efectiva = (parseInt(jornada_efectiva_horas.value * 60) + parseInt(jornada_efectiva_minutos.value));
    }
    var tiempo_pres = document.getElementById('tpen');
    if (tiempo_pres != null) {
        jsonObj.tiempo_pres = tiempo_pres.value;
    }

    var selectUbicacion = document.getElementById('id_ubicacion_fichaje');
    if (selectUbicacion != null) {
        var info_fichaje = strFichaje.split("_");
        if (selectUbicacion.options[selectUbicacion.selectedIndex].value != "") {
            jsonObj.id_ubicacion_fichaje = selectUbicacion.options[selectUbicacion.selectedIndex].value;
        } else if (info_fichaje[1] == 1 && checkUbicacion == true) {
            showDialog(mensaje_faltan_campos, 1);
            selectUbicacion.classList.add("requerido");
            return false;
        }
    }

    var url = "";
    var ajax = objetoAjax();
    url = "../common/save_elem.php";
    if ($("#id_centros").val() != "" || $(".ContenedorFichaje").css("display") === "none") {

        ajax.open("POST", url, true);
        ajax.setRequestHeader('Content-Type', 'application/json; charset=UTF-8');
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                    if (document.getElementById("fichadorModal") || document.getElementById("widget_fichaje_web")) {
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                listaFichajesQuick(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                listaFichajesQuick(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                listaFichajesQuick(arr_aux[1], 1);
                            }
                        } else {
                            listaFichajesQuick(noResults);
                        }
                    } else {
                        var html_txt = ajax.responseText;
                        if (html_txt != "") {
                            var arr_aux = html_txt.split("|");
                            if (arr_aux[0] == 1) {
                                showDialog(arr_aux[1]);
                            } else if (arr_aux[0] == 2) {
                                showDialog(arr_aux[1]);
                                flag_echar = true;
                            } else {
                                showDialog(arr_aux[1]);
                                irAContenido(menu_activo, menu_opcion, submenu_opcion);
                            }
                        } else {
                            showDialog(noResults);
                        }

                    }
                } else if (ajax.status == 404) {
                    showDialog(error404, 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        ajax.send(JSON.stringify(jsonObj));
        //ajax.send(formData);
        esperaRespuesta(true);
    } else {
        $("#id_centros").addClass("requerido");
        showDialog(mensaje_faltan_campos, 1);
    }
}
function btnScrollDatatable(submenu_opcion,divTable) {
    var button = document.createElement('div');
    button.id = 'scrollUpButton';
    button.innerHTML = '<i class="ti ti-chevron-up text-[30px]"></i>';
    button.classList.add('shadow-lg');
    button.style.margin = '10px'; // Estilo opcional para el botón

    var button2 = document.createElement('div');
    button2.id = 'scrollDownButton';
    button2.innerHTML = '<i class="ti ti-chevron-down text-[30px]"></i>';
    button2.classList.add('shadow-lg');
    button2.style.margin = '10px'; // Estilo opcional para el botón

    // Verificar si existe un botón con la clase 'button_denuncia'
    if (document.querySelector('.button_denuncia')) {
        button.style.bottom = '200px'; 
        button2.style.bottom = '150px';
    } else {
        button.style.bottom = '50px'; 
    }

    button.addEventListener('click', function() {
        divTable.scrollTop = 0; 
    });

    button2.addEventListener('click', function() {
         divTable.scrollTop = divTable.scrollHeight; 
    });

    // Agregar el botón al div
    var wrapper = document.getElementById('tabla_' + submenu_opcion + '_wrapper');

    if (wrapper) {
        wrapper.appendChild(button);
        wrapper.appendChild(button2);
    }
}

