// Posiciona el botón según el scroll
function btnUpdatePosicion(contenedor,idContenedorBoton) {
    var contenedorBoton = document.getElementById(idContenedorBoton);
    const visibleHeight = contenedor.clientHeight;
    const scrollTop = contenedor.scrollTop;
    contenedorBoton.style.top = (scrollTop + visibleHeight - 120) + 'px'; // 50px es el margen desde el borde inferior
    contenedorBoton.style.right = '10px';
}

function toggleTooltip(button) {
    const tooltip = button.nextElementSibling;
    if (!tooltip) return;

    // Cerrar otros tooltips
    document.querySelectorAll('.tooltip-content').forEach(t => {
        if (t !== tooltip) t.classList.add('hidden');
    });

    tooltip.classList.toggle('hidden');
}

// Cerrar tooltip si se hace clic fuera
document.addEventListener('click', function(e) {
    if (!e.target.closest('.tooltip-btn')) {
        document.querySelectorAll('.tooltip-content').forEach(t => t.classList.add('hidden'));
    }
});

function validarTipoCampos(elemento) {
    var valorCampo = elemento.value;
    tipocampo = document.getElementById("tipo_campos");
    if(valorCampo == tipo_campos_boolean){
        document.getElementById("flag_requerido").value = "0";
        tipocampo.classList.add("hidden");
    } else {
        document.getElementById("flag_requerido").value = "1";
        tipocampo.classList.remove("hidden");
    }
    const contenedorOpciones = document.getElementById('contenedor_opciones');
    if (contenedorOpciones) { // Buena práctica: verificar que el elemento exista
        if (valorCampo === tipo_campos_select) { // '6' es el valor para el tipo "Opciones"
            contenedorOpciones.classList.remove('hidden');
        } else {
            contenedorOpciones.classList.add('hidden');
            // Opcional: Si cambias de tipo y no es 'Opciones', podrías querer limpiar
            // las opciones que se hayan agregado previamente en 'opciones_container'.
            // const opcionesContainer = document.getElementById('opciones_container');
            if (opciones_container) {
                opciones_container.innerHTML = ''; // Limpiar las opciones agregadas
                limpiarOpcionesAgregadas();
            }
        }
    }

 } 
function fijarWidget(checkbox, id_widget, menu_opcion, submenu_opcion,confirm = 0) {
    var url = "../common/save_flag_widget_fijo.php";
    var ajax = objetoAjax();
    var estado = (confirm === 0) ? 1 : 0;
    var params = "op="+menu_opcion+"&sub="+submenu_opcion+"&id_widget=" + encodeURIComponent(id_widget) + "&estado=" + estado;

    // Condicional para mostrar confirmación si el checkbox está marcado
    if (!checkbox.checked && confirm == 0) {
        showConfirm(confirm_widget_fijo,fijarWidget,checkbox,id_widget,menu_opcion,submenu_opcion,1)
    }else{
        ajax.open("POST", url, true);
        ajax.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded; charset=UTF-8');
        
        ajax.onreadystatechange = function () {
            if (ajax.readyState == 4) {
                if (ajax.status == 200) {
                    esperaRespuesta(false);
                } else if (ajax.status == 404) {
                    showDialog("La página no existe", 1);
                } else if (ajax.status != 0) {
                    showDialog("Error:" + ajax.status, 1);
                }
            }
        };
        
        // Enviar los parámetros
        ajax.send(params);
        esperaRespuesta(true);
    }

}
