function showDialogComparaVacaciones(date, content) {
    var caja = document.getElementById('openModal');
    if (caja != null) {
        hideDialog();
        caja.appendChild(genContenidoDialogoComparaVacaciones(date, content));
        caja.style.opacity = 1;
        caja.style.pointerEvents = "auto";
    }
}
function genContenidoDialogoComparaVacaciones(date, content) {
    var divElement = document.createElement('div');
    divElement.className = '!px-5';
    var anchorElement = document.createElement('a');
    anchorElement.innerHTML = cerrar.toUpperCase();
    anchorElement.title = 'Close';
    anchorElement.id = 'botonPrincipal';
    anchorElement.className = '!text-[#2C2554] hover:!text-[#FFFFFF] !text-sm !py-2.5 !px-5 !rounded-full  hover:!bg-[#2C2554] !bg-[#FFFFFF] cursor-pointer buttonModal';
    anchorElement.onclick = function () {
        hideDialog();
        if (flag_echar == true) {
            window.location = "../inc/salir.php";
            flag_echar = false;
        } else if (flag_recarga == true) {
            window.location.reload();
            flag_recarga = false;
        }
    };
    var h2Element = document.createElement('h2');
    h2Element.className = "text-[30px]";
        h2Element.innerHTML = date;
    var pElement = document.createElement('p');
    var divContent = document.createElement('div');
    divContent.className = 'w-full flex justify-center mb-5 flex-col text-center';
    const items = JSON.parse(content);
    let modalContent = "";
    items.forEach(item => {
        const color = item.estado == 2 ? "bg-[#50C878]" : "bg-[#F8B730]";
        modalContent += `<div class="flex items-center"><span class="rounded-full p-1 w-[1px] h-[1px] mr-1 ${color}">&nbsp;</span> ${item.nombre}</div>`;
    });
    var divContentList = document.createElement('div'); 
    divContentList.className = "max-h-[50vh] overflow-x-hidden overflow-y-auto";
    divContentList.innerHTML = modalContent;
    var divButtons = document.createElement('div');
    divButtons.className = 'w-full flex justify-around';
    divButtons.appendChild(anchorElement);
    divContent.appendChild(h2Element);
    divContent.appendChild(divContentList);
    divElement.appendChild(divContent);
    divElement.appendChild(divButtons);
    return divElement;
}

function fechaComparaVacaciones(menu_opcion, submenu_opcion){
    // Obtener el valor del select
    var select = document.getElementById("ano");
    var year = select.value;
    var select2 = document.getElementById("mes");
    var mes = select2.value;
    var url = "";
    var ajax = objetoAjax();
    url = "../common/set_fecha_compara_vacaciones.php?y=" + year + "&m=" + mes;
    ajax.open("GET", url, true);
    ajax.onreadystatechange = function () {
        if (ajax.readyState == 4) {
            if (ajax.status == 200) {
                var html_txt = ajax.responseText;
                if (html_txt != "") {
                    var arr_aux = html_txt.split("|");
                    if (arr_aux[0] == 0) {
                        console.log(arr_aux);
                        irAContenido(menu_activo, menu_opcion, submenu_opcion);
                    }
                } else {
                    showDialog(noResults);
                }
            } else if (ajax.status == 404) {
                showDialog(error404, 1);
            }
            else if (ajax.status != 0) {
                showDialog("Error:" + ajax.status, 1);
            }
        }
    };
    ajax.send(null);
}
function reorderSelectOptions() {
    const select = document.getElementById('tarjetas');
    if (!select) return;

    const options = Array.from(select.options);
    const selected = options.filter(opt => opt.selected);
    const unselected = options.filter(opt => !opt.selected);

    select.innerHTML = '';
    selected.concat(unselected).forEach(opt => select.appendChild(opt));

    $(select).pqSelect('destroy');
    $(select).pqSelect({
        checkbox: true,
        multiplePlaceholder: 'Seleccionados {0} de {1}',
        singlePlaceholder: 'Seleccionado 1 de {1}',
        width: '100%', 
        maxDisplay: 0 
    });  
    buscarSiCodigoQR(); 
}

function agregarOpcion() {
    const inputOpcion = document.getElementById('opciones_input');
    const containerOpciones = document.getElementById('opciones_container');
    const valorOpcion = inputOpcion.value.trim();
    const formPrincipal = document.getElementById('nuevo_elemento'); // Asegúrate que este es el ID de tu formulario

    if (valorOpcion === "") {
        // Opcional: Mostrar un mensaje si el campo está vacío
        // alert("Por favor, ingrese un valor para la opción.");
        return;
    }

    if (!formPrincipal) {
        console.error("El formulario con id 'nuevo_elemento' no fue encontrado.");
        return;
    }

    opcionUnicaCounter++;
    const idInputHidden = 'opcion_hidden_' + opcionUnicaCounter;

    // Crear el input hidden
    const nuevoInputHidden = document.createElement('input');
    nuevoInputHidden.type = 'hidden';
    nuevoInputHidden.name = 'opciones[]'; // Nombre del arreglo para PHP
    nuevoInputHidden.value = valorOpcion;
    nuevoInputHidden.id = idInputHidden;

    // Agregar el input hidden al formulario
    formPrincipal.appendChild(nuevoInputHidden);

    // Crear un nuevo elemento visual para la opción
    const nuevaOpcionDiv = document.createElement('div');
    nuevaOpcionDiv.classList.add('opcion-item', 'flex', 'justify-between', 'items-center', 'p-1', 'bg-gray-100', 'rounded', 'mb-1');
    // Guardar el ID del input hidden asociado para poder removerlo después
    nuevaOpcionDiv.setAttribute('data-hidden-input-id', idInputHidden);
    
    const textoOpcion = document.createElement('span');
    textoOpcion.textContent = valorOpcion;
    nuevaOpcionDiv.appendChild(textoOpcion);

    // Crear botón para eliminar la opción (visual y hidden)
    const botonEliminar = document.createElement('button');
    botonEliminar.textContent = 'X';
    botonEliminar.classList.add('text-red-500', 'hover:text-red-700', 'ml-2');
    botonEliminar.onclick = function() {
        // Remover el input hidden del formulario
        const idHiddenARemover = nuevaOpcionDiv.getAttribute('data-hidden-input-id');
        const inputHiddenARemover = document.getElementById(idHiddenARemover);
        if (inputHiddenARemover) {
            inputHiddenARemover.remove();
        }
        // Remover el elemento visual
        containerOpciones.removeChild(nuevaOpcionDiv);
    };
    nuevaOpcionDiv.appendChild(botonEliminar);

    // Agregar la nueva opción visual al contenedor
    containerOpciones.appendChild(nuevaOpcionDiv);

    // Limpiar el campo de entrada
    inputOpcion.value = "";
    inputOpcion.focus();
}

// Considera también limpiar los inputs hidden si el tipo de campo cambia y ya no es 'select'
// Esto podría ir en tu función validarTipoCampos
function limpiarOpcionesAgregadas() {
    const formPrincipal = document.getElementById('nuevo_elemento');
    if (!formPrincipal) return;

    const inputsOcultos = formPrincipal.querySelectorAll('input[type="hidden"][name="opciones[]"]');
    inputsOcultos.forEach(input => input.remove());

    const containerOpciones = document.getElementById('opciones_container');
    if (containerOpciones) {
        containerOpciones.innerHTML = '<!-- Las opciones agregadas aparecerán aquí -->';
    }
    opcionUnicaCounter = 0; // Resetear el contador si es necesario
}
